window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 295, "text": "Что делать водителю, если он едет за другим транспортным средством, которое не собирается обгонять?", "topic": "Обгін та зміна смуги руху", "options": ["Ехать ближе к нему, чтобы позволить другим транспортным средствам совершить обгон обоих автомобилей.", "Подать сигнал автомобилям, едущим за вами, о возможности обогнать оба транспортных средства.", "Держаться подальше от автомобиля, ближе к центру дороги.", "Держаться подальше, чтобы позволить автомобилям, едущим за вами, совершить обгон."], "correct": 3, "expl": "Якщо водій їде за транспортом, який не збирається обганяти, і сам не планує обгін, варто триматися на більшій дистанції, щоб залишити простір для транспорту позаду.", "explSpecific": "Правильно — «Держаться подальше, чтобы позволить автомобилям, едущим за вами, совершить обгон». Наближення впритул чи зміщення до центру дороги ускладнюють обгін для транспорту позаду."}, {"num": 296, "text": "Почему движение вплотную к впереди идущему автомобилю опасно?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Тормозная система менее эффективна в потоке автомобилей, едущих впереди.", "Двигатель может перегреться из-за ограниченного воздушного потока над двигателем транспортного средства.", "Транспортное средство не будет иметь достаточного расстояния для безопасной остановки в чрезвычайной ситуации.", "Транспортное средство превысит ограничение скорости."], "correct": 2, "expl": "Рух впритул до автомобіля попереду небезпечний насамперед тому, що не залишає достатньо простору й часу для повної зупинки в разі раптового гальмування переднього транспорту.", "explSpecific": "Правильно — «Транспортное средство не будет иметь достаточного расстояния для безопасной остановки». Перегрів двигуна через обмежений потік повітря чи менш ефективна гальмівна система — фізично необґрунтовані твердження; перевищення обмеження швидкості не є прямим наслідком руху впритул."}, {"num": 297, "text": "Разрешено ли движение вплотную к впереди идущему автомобилю на автомагистрали или на двойной проезжей части?", "topic": "Автомагістраль і тунелі", "options": ["Да, поскольку есть встречное движение.", "Да, поскольку все транспортные средства движутся в одном направлении одновременно.", "Нет, поскольку автомобиль, едущий впереди, может внезапно остановиться.", "Нет, поскольку другие транспортные средства не имеют пространства для обгона."], "correct": 2, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Нет, поскольку автомобиль, едущий впереди, может внезапно остановиться». Інші варіанти в цьому питанні («Да, поскольку есть встречное движение», «Да, поскольку все транспортные средства движутся в одном направлении одновременно» та «Нет, поскольку другие транспортные средства не имеют пространства для обгона») не відповідають цій вимозі й тому неправильні."}, {"num": 298, "text": "Какая опасность может возникнуть при дневном свете, когда водитель входит в зону, сильно затененную нависающими деревьями?", "topic": "Погодні умови та видимість", "options": ["Видимость может внезапно ухудшиться.", "Двигатель автомобиля может внезапно остыть.", "Лобовое стекло автомобиля может запотеть.", "Давление в шинах может быть уменьшено."], "correct": 0, "expl": "В'їжджаючи в різко затінену деревами ділянку дороги при яскравому денному світлі, очі водія не встигають миттєво адаптуватися, тому видимість тимчасово різко погіршується.", "explSpecific": "Правильно — «Видимость может внезапно ухудшиться». Твердження про раптове охолодження двигуна, запотівання скла чи падіння тиску в шинах — вигадані, не пов'язані з тінню наслідки."}, {"num": 299, "text": "Что следует делать водителю при обгоне другим транспортным средством?", "topic": "Обгін та зміна смуги руху", "options": ["Увеличить скорость.", "Продолжать движение с той же скоростью.", "Быстро замедлиться.", "Съехать вправо."], "correct": 1, "expl": "Коли інший водій обганяє вас, найправильніше — зберігати свою поточну швидкість, не прискорюючись і не сповільнюючись різко, щоб маневр пройшов передбачувано.", "explSpecific": "Правильно — «Продолжать движение с той же скоростью». Збільшення швидкості перетворює обгін на небезпечні перегони; різке сповільнення чи з'їзд праворуч без потреби порушують передбачуваність маневру."}, {"num": 300, "text": "Когда следует подавать сигнал (например, поворотными сигнальными огнями) другим участникам дорожного движения", "topic": "Дорожні знаки та розмітка", "options": ["При повороте, кроме случаев, когда дорожная разметка указывает ваше направление.", "Только тогда, когда необходимо предупредить следующие за вами транспортные средства.", "Только тогда, когда необходимо предупредить встречные транспортные средства.", "Ясно и своевременно сообщить другим участникам дорожного движения о ваших намерениях."], "correct": 3, "expl": "Сигналізувати про свої наміри (наприклад, поворотниками) потрібно чітко і завчасно для всіх учасників руху, а не лише для окремої категорії чи напрямку.", "explSpecific": "Правильно — «Ясно и своевременно сообщить другим участникам дорожного движения о ваших намерениях». «Тільки при повороті, крім розмітки» звужує сигнал до одного маневру; «тільки для транспорту позаду/назустріч» обмежує адресатів сигналу, хоча він призначений для всіх."}, {"num": 301, "text": "Как поздний сигнал влияет на других участников дорожного движения?", "topic": "Дорожні знаки та розмітка", "options": ["Это не влияет на их действия.", "Это влияет только на других участников дорожного движения на светофоре.", "Возможно, им будет недостаточно времени, чтобы среагировать.", "Это влияет только на других участников дорожного движения на кольцевой развязке."], "correct": 2, "expl": "Запізніла сигналізація про маневр залишає іншим учасникам руху менше часу на реакцію, підвищуючи ризик ДТП.", "explSpecific": "Правильно — «Возможно, им будет недостаточно времени, чтобы среагировать». «Не впливає на дії» прямо суперечить логіці попередження про наміри; звуження ефекту лише до світлофора чи кільцевої розв'язки штучно обмежує наслідок пізнього сигналу."}, {"num": 302, "text": "При движении с узким зазором между встречными транспортными средствами и припаркованными транспортными средствами слева. Как водителю следует поступить?", "topic": "Паркування та зупинка", "options": ["Указать поворот направо, остановиться при необходимости, пока не встречные транспортные средства не проедут.", "Подать сигнал и продолжать движение.", "Подать сигнал встречным транспортным средствам, затем съехать вправо и двигаться в обычном режиме.", "Всегда замедляться, останавливаться и дожидаться сигнала встречного автомобиля."], "correct": 0, "expl": "Рухаючись у вузькому проміжку між зустрічним транспортом і припаркованими машинами зліва, водій повинен позначити намір (сигналом праворуч) і за потреби зупинитися, пропустивши зустрічний транспорт.", "explSpecific": "Правильно — «Указать поворот направо, остановиться при необходимости, пока не встречные транспортные средства не проедут». Продовження руху без зупинки чи сигналізація зустрічним, щоб вони самі з'їхали, — небезпечні очікування у вузькому проміжку."}, {"num": 303, "text": "Как дождь влияет на вождение в этой ситуации?", "topic": "Погодні умови та видимість", "options": ["Он увеличивает сцепление шин с дорогой.", "Он повышает видимость.", "Он снижает опасность скольжения.", "Он увеличивает опасность скольжения."], "correct": 3, "expl": "Дощ знижує зчеплення шин з дорогою, підвищуючи ризик ковзання (заносу) незалежно від конкретної ситуації на дорозі.", "explSpecific": "Правильно — «Он увеличивает опасность скольжения». Твердження про покращення зчеплення, видимості чи зниження небезпеки ковзання прямо суперечать фізичному ефекту дощу на дорожнє покриття.", "img": "q303.png"}, {"num": 304, "text": "Что должен делать водитель, когда находится на перекрестке с крайне ограниченной видимостью?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Двигаться с особой осторожностью, внимательно посмотрев влево и вправо.", "Посигналить и быстро проехать.", "Обратиться за помощью к прохожему.", "Выйти из машины на дорогу, чтобы другие водители могли его видеть."], "correct": 0, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Двигаться с особой осторожностью, внимательно посмотрев влево и вправо». Інші варіанти в цьому питанні («Посигналить и быстро проехать», «Обратиться за помощью к прохожему» та «Выйти из машины на дорогу, чтобы другие водители могли его видеть») не відповідають цій вимозі й тому неправильні."}, {"num": 305, "text": "Когда водитель должен использовать зеркало заднего вида автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Прежде чем сменить направление.", "Только перед разворотом.", "Перед включением задней системы обдува стекол.", "Только перед тем, как тронуться с места."], "correct": 0, "expl": "Дзеркало заднього виду потрібно перевіряти перед будь-якою зміною напрямку руху — поворотом, перестроюванням чи обгоном, а не лише в окремих спеціальних ситуаціях.", "explSpecific": "Правильно — «Прежде чем сменить направление». Прив'язка лише до розвороту, обдуву скла чи рушання з місця невиправдано звужує момент, коли перевірка дзеркала дійсно необхідна."}, {"num": 306, "text": "Как следует действовать водителю, если видимость на перекрестке ограничена?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Спросите у прохожего, как проехать на другую дорогу.", "Медленно выехать на дорогу, внимательно следя за другим транспортом.", "Посигналить несколько раз и продолжать движение.", "Включить и выключить фары, прежде чем тронуться с места."], "correct": 1, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Медленно выехать на дорогу, внимательно следя за другим транспортом». Інші варіанти в цьому питанні («Спросите у прохожего, как проехать на другую дорогу», «Посигналить несколько раз и продолжать движение» та «Включить и выключить фары, прежде чем тронуться с места») не відповідають цій вимозі й тому неправильні."}, {"num": 307, "text": "Что делать водителю приближаясь к светофору, заклинившем на красном свете?", "topic": "Дорожні знаки та розмітка", "options": ["Посигналить и проехать.", "Остановиться и осторожно продолжить движение.", "Укажите и увеличьте скорость.", "Проверьте, что нет встречных транспортных средств и увеличьте скорость."], "correct": 1, "expl": "Коли світлофор «заклинив» на червоному тривалий час, водій повинен зупинитися і, переконавшись у безпеці, обережно продовжити рух, а не ігнорувати сигнал повністю чи прискорюватися.", "explSpecific": "Правильно — «Остановиться и осторожно продолжить движение». «Посигналити і проїхати» та «збільшити швидкість» ігнорують обов'язок спершу зупинитися; «перевірити відсутність зустрічних і збільшити швидкість» пропускає необхідну обережність при русі далі."}, {"num": 308, "text": "Как должен действовать водитель в пасмурный день в условиях ухудшенной видимости?", "topic": "Погодні умови та видимість", "options": ["Ехать с включенными фарами дальнего света.", "Водитель не должен включать фары в часы хорошей освещенности.", "Ехать с включенными фарами ближнего света.", "Держаться ближе к любому транспортному средству впереди с выключенными фарами."], "correct": 2, "expl": "У похмурий день з погіршеною видимістю навіть удень варто вмикати фари ближнього світла, щоб бути помітним для інших учасників руху.", "explSpecific": "Правильно — «Ехать с включенными фарами ближнего света». Дальнє світло вдень недоречне й може засліпити зустрічних; повна відмова від фар при поганій видимості небезпечна."}, {"num": 309, "text": "Как водителю следует действовать при езде за тяжелым грузовым автомобилем, который сигнализирует о повороте вправо?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Оставаться позади, пока не появится достаточно пространства, чтобы обогнать его по внутренней полосе или пока автомобиль не завершит поворот.", "Успеть обогнать грузовик, пока тот не повернул.", "Сигналить водителю грузовика до тех пор, пока он не уступит дорогу.", "Смотреть в зеркало заднего вида."], "correct": 0, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Оставаться позади, пока не появится достаточно пространства, чтобы обогнать его по внутренней полосе или пока автомобиль не завершит поворот». Інші варіанти в цьому питанні («Успеть обогнать грузовик, пока тот не повернул», «Сигналить водителю грузовика до тех пор, пока он не уступит дорогу» та «Смотреть в зеркало заднего вида») не відповідають цій вимозі й тому неправильні."}, {"num": 310, "text": "Что должен делать водитель, когда едет за автобусом, который сигнализирует о повороте налево и встречном движении?", "topic": "Паркування та зупинка", "options": ["Остановиться и дать ему завершить поворот.", "Притормозить и подать звуковой сигнал, чтобы предупредить другие автомобили о необходимости замедлиться.", "Обогнать его справа.", "Обогнать его слева."], "correct": 0, "expl": "Якщо автобус попереду сигналізує поворот ліворуч за наявності зустрічного руху, водій позаду повинен зупинитися і дати йому спокійно завершити маневр.", "explSpecific": "Правильно — «Остановиться и дать ему завершить поворот». Обгін автобуса праворуч чи ліворуч під час його маневру повороту — небезпечний і непередбачуваний для самого автобуса; звуковий сигнал іншим авто не замінює власної зупинки."}, {"num": 311, "text": "Что делать водителю при езде по широкой дороге за автомобилем, который подал знак о повороте направо?", "topic": "Дорожні знаки та розмітка", "options": ["Совершить обгон слева, но только если точка поворота налево находится на небольшом расстоянии впереди.", "Остаться позади и притормозить, чтобы подать сигнал другим водителям, чтобы они замедлились.", "Совершить обгон слева и продолжать движение, если это безопасно.", "Совершить обгон справа и продолжить движение."], "correct": 2, "expl": "Обганяючи транспорт, що подав сигнал повороту праворуч на широкій дорозі, безпечніше проїхати зліва від нього, зберігаючи дистанцію, а не праворуч, де він саме має намір повернути.", "explSpecific": "Правильно — «Совершить обгон слева и продолжать движение, если это безопасно». Обгін праворуч небезпечний саме тому, що транспорт попереду повертає туди ж; «залишитися позаду» не є обгоном взагалі; умова «лише якщо поворот далеко» вигадує обмеження, не властиве загальному правилу безпечного обгону зліва."}, {"num": 312, "text": "Согласно Отчету о ДТП, по вине нетрезвых водителей каких транспортных средств происходило большинство столкновений со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Мотоцикл.", "Трактор.", "Грузовой автомобиль.", "Любой автомобиль."], "correct": 3, "expl": "Це вразливі учасники руху — при зіткненні саме вони найбільше постраждають, тому правила завжди вимагають від водія автомобіля брати на себе більше відповідальності: пропускати, давати більшу дистанцію при обгоні, бути особливо уважним на переходах і перехрестях, де пішохід чи велосипедист може бути непомітний (сліпі зони, дзеркала). Правильна відповідь у цій темі майже завжди та, що надає їм пріоритет або збільшує дистанцію до них.", "explSpecific": "Правильна відповідь тут — «Любой автомобиль». Інші варіанти в цьому питанні («Мотоцикл», «Трактор» та «Трактор») не відповідають цій вимозі й тому неправильні."}, {"num": 313, "text": "Согласно Отчету о ДТП, к какому типу столкновений со смертельным исходом человек мог быть причастен при вождении в нетрезвом виде?", "topic": "Статистика ДТП", "options": ["Столкновение с участием одного автомобиля.", "Столкновение с пешеходом.", "Столкновение с мотоциклистом.", "Столкновение с участием нескольких автомобилей."], "correct": 0, "expl": "Це вразливі учасники руху — при зіткненні саме вони найбільше постраждають, тому правила завжди вимагають від водія автомобіля брати на себе більше відповідальності: пропускати, давати більшу дистанцію при обгоні, бути особливо уважним на переходах і перехрестях, де пішохід чи велосипедист може бути непомітний (сліпі зони, дзеркала). Правильна відповідь у цій темі майже завжди та, що надає їм пріоритет або збільшує дистанцію до них.", "explSpecific": "Правильна відповідь тут — «Столкновение с участием одного автомобиля». Інші варіанти в цьому питанні («Столкновение с пешеходом», «Столкновение с мотоциклистом» та «Столкновение с участием нескольких автомобилей») не відповідають цій вимозі й тому неправильні."}, {"num": 314, "text": "О какой слепой зоне водитель должен помнить при буксировке загруженного прицепа?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Участки сбоку и сзади от автомобиля и прицепа, которые водитель не может видеть.", "Участки дороги впереди, которые закрыты другими крупными транспортными средствами.", "Грузовой отсек в задней части прицепа.", "Вид спереди, скрытый солнцезащитным козырьком."], "correct": 0, "expl": "Великогабаритний транспорт і техніка з причепом мають більшу масу, довший гальмівний шлях, більші сліпі зони та вищий ризик перекидання на поворотах чи нерівностях. Тому логіка тут — рухатися повільніше, забезпечувати більшу дистанцію та бути особливо обережним на кільцевих розв'язках і поворотах, де причіп може «зрізати» траєкторію. Це пояснює, чому правильні відповіді часто пов'язані зі зниженням швидкості або додатковою перевіркою перед маневром.", "explSpecific": "Правильна відповідь тут — «Участки сбоку и сзади от автомобиля и прицепа, которые водитель не может видеть». Інші варіанти в цьому питанні («Участки дороги впереди, которые закрыты другими крупными транспортными средствами», «Грузовой отсек в задней части прицепа» та «Вид спереди, скрытый солнцезащитным козырьком») не відповідають цій вимозі й тому неправильні."}, {"num": 315, "text": "Когда разрешается совершать обгон другого автомобиля слева?", "topic": "Обгін та зміна смуги руху", "options": ["Только если нет велосипедной дорожки.", "Когда есть три полосы движения с быстро движущимися транспортными средствами.", "Когда автомобиль спереди подает сигнал о своем намерении повернуть направо.", "Водитель никогда не должен обгонять слева."], "correct": 2, "expl": "Обгін зліва дозволений як виняток саме тоді, коли транспорт попереду сигналізує намір повернути праворуч, звільняючи для обгону лівий бік дороги.", "explSpecific": "Правильно — «Когда автомобиль спереди подает сигнал о своем намерении повернуть направо». Наявність велосипедної доріжки чи трьох смуг самі по собі не є визначальною умовою; заборона «ніколи не обганяти зліва» суперечить наявному винятку."}, {"num": 316, "text": "Как должен действовать водитель, желающий развернуться?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Убедиться, что дорога, по которой он движется, не является дорогой с односторонним движением.", "Убедиться, что на горизонте нет других автомобилей.", "Убедиться, что вблизи нет общественных и социальных объектов.", "Включить поворотные огни и, посмотрев по сторонам, развернуться."], "correct": 0, "expl": "Перш ніж розвертатися, водій повинен переконатися, що сам маневр взагалі дозволений на цій дорозі — зокрема, що дорога не є односторонньою, де розворот неможливий за визначенням.", "explSpecific": "Правильно — «Убедиться, что дорога... не является дорогой с односторонним движением». Перевірка горизонту чи відсутність поруч соціальних об'єктів — вигадані критерії; увімкнення поворотників саме по собі не гарантує, що маневр взагалі дозволений."}, {"num": 317, "text": "Как должен действовать водитель, желающий развернуться?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Убедиться в отсутствии встречных транспортных средств быстро выполнить разворот, при этом следя за обстановкой на дороге.", "Выехать на проезжую часть другого транспортного средства и повернуть обратно на дорогу.", "Разворот запрещен при любых обстоятельствах", "При необходимости, выехать на тротуар, чтобы обеспечить достаточно пространства для маневра."], "correct": 0, "expl": "Виконуючи розворот, водій повинен переконатися у відсутності зустрічного транспорту і виконати маневр швидко й рішуче, постійно контролюючи ситуацію навколо.", "explSpecific": "Правильно — «Убедиться в отсутствии встречных транспортных средств... следя за обстановкой». Виїзд на смугу зустрічного руху чи на тротуар небезпечні й неприпустимі; повна заборона розвороту за будь-яких обставин перебільшена."}, {"num": 318, "text": "Как следует поступить водителю в случае сонливости во время управления автомобилем?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Остановиться и плотно поесть, чтобы повысить уровень энергии.", "Включить печку.", "Остановиться, передохнуть и немного пройтись, если возможно.", "Открыть окно или включить кондиционер, чтобы впустить в автомобиль прохладный воздух."], "correct": 2, "expl": "Правила зупинки й парковки будуються навколо трьох речей: не створювати перешкоду для руху, не закривати огляд іншим учасникам (особливо на перехрестях і пішохідних переходах) і не наражати на небезпеку тих, хто виходить з машини. Тому заборонено зупинятись близько до перехрестя, на пішохідному переході, у місцях з подвійною жовтою лінією чи де це прямо заборонено знаком. Правильна відповідь зазвичай та, що залишає достатньо простору та видимості для інших.", "explSpecific": "Правильна відповідь тут — «Остановиться, передохнуть и немного пройтись, если возможно». Інші варіанти в цьому питанні («Остановиться и плотно поесть, чтобы повысить уровень энергии», «Включить печку» та «Открыть окно или включить кондиционер, чтобы впустить в автомобиль прохладный воздух») не відповідають цій вимозі й тому неправильні."}, {"num": 319, "text": "Что делать водителю, если он почувствует усталость за рулем?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Водитель должен остановиться и передохнуть.", "Водитель должен увеличить скорость, чтобы быстрее добраться до пункта назначения.", "Водитель должен ехать по центру дороги на сниженной скорости.", "Водитель должен ехать по укрепленной части обочины, где это возможно."], "correct": 0, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Водитель должен остановиться и передохнуть». Інші варіанти в цьому питанні («Водитель должен увеличить скорость, чтобы быстрее добраться до пункта назначения», «Водитель должен ехать по центру дороги на сниженной скорости» та «Водитель должен ехать по укрепленной части обочины, где это возможно») не відповідають цій вимозі й тому неправильні."}, {"num": 320, "text": "Что делать водителю, если он не успевает вовремя добраться до пункта назначения?", "topic": "Обгін та зміна смуги руху", "options": ["Успокоиться и ехать так, чтобы благополучно добраться до пункта назначения.", "Ехать по укрепленной части обочины, где это возможно.", "Ехать быстро и обгонять любые транспортные средства на пути.", "При необходимости, превысить ограничение скорости, чтобы вовремя добраться до пункта назначения."], "correct": 0, "expl": "Якщо водій запізнюється, правильна реакція — заспокоїтися і продовжувати їхати безпечно, а не намагатися надолужити час ризикованими діями.", "explSpecific": "Правильно — «Успокоиться и ехать так, чтобы благополучно добраться до пункта назначения». Рух по узбіччю, агресивний обгін усіх підряд чи перевищення швидкості — небезпечні спроби компенсувати запізнення."}, {"num": 321, "text": "Как следует действовать водителю, если он движется не так быстро, как автомобиль впереди?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель должен включить аварийные огни и держаться левее.", "Водитель должен держаться левой стороны, чтобы транспортные средства, при желании, могли совершить обгон.", "Водитель должен указать транспорту на возможность обогнать его, подав сигнал рукой.", "Водитель должен сохранять свое положение и не допускать обгона следующими за ним транспортными средствами."], "correct": 1, "expl": "Якщо водій рухається повільніше за бажаний темп потоку, варто триматися лівого боку смуги, полегшуючи іншим обгін за бажання.", "explSpecific": "Правильно — «Водитель должен держаться левой стороны, чтобы транспортные средства, при желании, могли совершить обгон». Аварійні вогні тут не потрібні; сигнал рукою про дозвіл обгону чи навмисне перешкоджання — недоречні дії."}, {"num": 322, "text": "Что делать водителю, если он хочет проехать по оживленной дороге, а светофоры, которые обычно регулируют перекресток, временно не работают?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Посигналить и медленно пересечь дорогу.", "Внимательно посмотреть по сторонам, дождаться остановки транспорта и продолжить движение.", "Медленно проехать, включив, при необходимости, сигнальные огни.", "Включить фары и использовать сигналы рукой, чтобы показать другим водителям о своем намерении проехать и затем продолжить движение."], "correct": 1, "expl": "Форма і колір знаку самі по собі несуть значення, ще до того, як прочитано текст. Червоний восьмикутник — це завжди STOP: повна зупинка, незалежно від ситуації на дорозі. Червоне коло — заборона; трикутник із червоною облямівкою — попередження про небезпеку попереду; синє коло — обов'язкова вказівка (те, що треба зробити, а не те, чого не можна); синій або зелений прямокутник — інформаційний знак (напрямок, назва, відстань). Розмітка на дорозі працює за тією ж логікою: суцільна лінія забороняє перетин, переривчаста дозволяє за умови безпеки, подвійна суцільна діє найсуворіше в обох напрямках.", "explSpecific": "Порівняй формулювання: правильна відповідь передбачає дію «Внимательно посмотреть по сторонам, дождаться остановки транспорта и продолжить движение», а один із неправильних варіантів пропонує протилежне — «Медленно проехать, включив, при необходимости, сигнальные огни». Це невипадково: правильна дія — почекати, поки ситуація стане безпечною, а не рухатись одразу."}, {"num": 323, "text": "Что должен сделать водитель, если увидит, что впереди остановился школьный автобус (с левой стороны)?", "topic": "Обгін та зміна смуги руху", "options": ["Посигналить и сохранить текущую скорость.", "Включить аварийные огни и остановиться за автобусом.", "Посигналить и продолжить движение.", "Снизить скорость и осторожно совершить обгон."], "correct": 3, "expl": "Побачивши попереду зупинений шкільний автобус, водій повинен знизити швидкість і обережно об'їхати його, стежачи за дітьми навколо.", "explSpecific": "Правильно — «Снизить скорость и осторожно совершить обгон». Сигнал з продовженням тієї ж швидкості ігнорує ризик появи дітей; зупинка з аварійними вогнями позаду автобуса — надмірна реакція, якщо об'їзд можливий безпечно."}, {"num": 324, "text": "Как должен поступить водитель, если едет за автомобилем, который небезопасным образом виляет из стороны в сторону по дороге?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель должен подать сигнал и объехать такой автомобиль справа.", "Водитель должен подъехать вплотную к транспортному средству сзади, чтобы совершить обгон.", "Водитель должен подать сигнал и объехать такой автомобиль слева.", "Водитель должен оставаться на безопасном расстоянии позади автомобиля."], "correct": 3, "expl": "Якщо транспорт попереду небезпечно вихляє по дорозі, найбезпечніше — триматися на безпечній дистанції позаду, а не намагатися обігнати непередбачуваний автомобіль.", "explSpecific": "Правильно — «Водитель должен оставаться на безопасном расстоянии позади автомобиля». Обгін праворуч чи ліворуч непередбачуваного автомобіля значно підвищує ризик зіткнення."}, {"num": 325, "text": "Что делать водителю, если большегрузный автомобиль впереди выехал для того, чтобы повернуть налево?", "topic": "Обгін та зміна смуги руху", "options": ["Двигаться к пространству с левой стороны.", "Оставаться позади него, и дать ему завершить поворот.", "Немедленно выехать и совершить обгон как можно быстрее.", "Переместиться вправо, но не обгонять."], "correct": 1, "expl": "Якщо великогабаритний транспорт попереду виїхав на позицію для повороту ліворуч, водій повинен залишатися позаду і дати йому спокійно завершити маневр.", "explSpecific": "Правильно — «Оставаться позади него, и дать ему завершить поворот». Рух у простір ліворуч чи негайний обгін небезпечні, оскільки великий транспорт потребує більше простору для повороту."}, {"num": 326, "text": "Что делать водителю, если автобус, едущий впереди, выехал, чтобы повернуть налево при наличии встречного движения?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Обогнать справа.", "Оставаться сзади и позволить автобусу завершить поворот.", "Обогнать слева.", "Сохранять скорость, до тех пор, пока он не окажется прямо сзади автобуса."], "correct": 1, "expl": "Великогабаритний транспорт і техніка з причепом мають більшу масу, довший гальмівний шлях, більші сліпі зони та вищий ризик перекидання на поворотах чи нерівностях. Тому логіка тут — рухатися повільніше, забезпечувати більшу дистанцію та бути особливо обережним на кільцевих розв'язках і поворотах, де причіп може «зрізати» траєкторію. Це пояснює, чому правильні відповіді часто пов'язані зі зниженням швидкості або додатковою перевіркою перед маневром.", "explSpecific": "Правильна відповідь тут — «Оставаться сзади и позволить автобусу завершить поворот». Інші варіанти в цьому питанні («Обогнать справа», «Обогнать слева» та «Сохранять скорость, до тех пор, пока он не окажется прямо сзади автобуса») не відповідають цій вимозі й тому неправильні."}, {"num": 327, "text": "Что должен сделать водитель, если увидит грузовик, поворачивающий в боковой съезд слева от дороги?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Постараться обогнать его, чтобы не доставлять неудобства транспорту позади.", "Подъехать ближе к грузовику и остановиться.", "Аккуратно остановиться и дождаться, пока путь не освободится.", "Подать звуковой сигнал, чтобы указать водителю грузовика о необходимости остановиться."], "correct": 2, "expl": "У складних погодних умовах (дощ, туман, ожеледь, темрява) гальмівний шлях зростає, а видимість — падає, тому логіка завжди одна: знизити швидкість і збільшити дистанцію до попереднього автомобіля пропорційно погіршенню умов. У тумані використовують ближнє світло (не дальнє — воно відбивається від крапель вологи і засліплює самого водія), а протитуманні фари вмикають лише за дійсно поганої видимості. Це пояснює, чому відповіді на кшталт «зменшити швидкість», «збільшити дистанцію» чи «увімкнути ближнє світло» майже завжди правильні в цій темі.", "explSpecific": "Правильна відповідь тут — «Аккуратно остановиться и дождаться, пока путь не освободится». Інші варіанти в цьому питанні («Постараться обогнать его, чтобы не доставлять неудобства транспорту позади», «Подъехать ближе к грузовику и остановиться» та «Подать звуковой сигнал, чтобы указать водителю грузовика о необходимости остановиться») не відповідають цій вимозі й тому неправильні."}, {"num": 328, "text": "Что делать водителю, если он первым в очереди поворачивает направо на светофоре, когда горит зеленый свет, и при этом к нему приближается встречный транспорт?", "topic": "Дорожні знаки та розмітка", "options": ["Оставаться на стоп-линии, пока не загорится зеленая стрелка.", "Подождать на стоп-линии, пока не загорится желтый свет, а затем повернуть.", "Двигаться вперед к центру развязки и совершить безопасный поворот, когда появится подходящий зазор.", "Оставаться на стоп-линии, и дождаться, пока в полосе встречного движения не появится подходящий зазор для поворота."], "correct": 2, "expl": "На перехресті зі світлофором водій, що повертає праворуч першим у черзі назустріч зустрічному потоку, за наявності «жовтої сітки» посередині може виїхати на перехрестя і завершити поворот, коли з'явиться безпечний проміжок, а не чекати на стоп-лінії безкінечно.", "explSpecific": "Правильно — «Двигаться вперед к центру развязки и совершить безопасный поворот, когда появится подходящий зазор». Очікування на стоп-лінії до зеленої стрілки чи жовтого світла невиправдано затримує рух і суперечить призначенню жовтої сітки на перехресті саме для такого маневру."}, {"num": 329, "text": "Когда разрешается вынуждать встречный транспорт выезжать на укрепленную часть обочины на противоположной стороне дороги при обгоне?", "topic": "Обгін та зміна смуги руху", "options": ["Когда укрепленная часть обочины достаточно широкая.", "При обгоне запрещается вынуждать встречный транспорт выезжать на укрепленную часть обочины.", "Когда ни одно из встречных транспортных средств не совершает обгон.", "Когда обгоняемое транспортное средство движется слишком медленно."], "correct": 1, "expl": "Під час обгону водієві заборонено змушувати зустрічний транспорт з'їжджати на укріплену частину узбіччя — маневр обгону завжди має залишати зустрічним повну їхню смугу.", "explSpecific": "Правильно — «При обгоне запрещается вынуждать встречный транспорт выезжать на укрепленную часть обочины» — без винятків. Умови про ширину узбіччя чи повільність обгонюваного транспорту не скасовують цю заборону."}, {"num": 330, "text": "Согласно Отчету о ДТП, в какие дни недели существовала большая вероятность вождения в нетрезвом виде, которое влекло за собой столкновение со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Четверг и Пятница", "Воскресенье и понедельник", "Суббота и воскресенье", "Пятница и суббота"], "correct": 2, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Суббота и воскресенье». Інші варіанти в цьому питанні («Четверг и Пятница», «Воскресенье и понедельник» та «Пятница и суббота») не відповідають цій вимозі й тому неправильні."}, {"num": 331, "text": "В случае встречного движения по автостраде, разрешается ли выезжать на укрепленный участок обочины, чтобы позволить следующему за вами транспорту совершить обгон?", "topic": "Автомагістраль і тунелі", "options": ["Да, когда на встречу едет грузовик или автобус.", "Нет, кроме как на дорогах типа 2+1.", "Нет, ехать по укрепленному участку обочины разрешается только в экстренных случаях.", "Да, временно, когда на укрепленному участке обочины нет никого и проезд по нему будет безопасным."], "correct": 3, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Да, временно, когда на укрепленному участке обочины нет никого и проезд по нему будет безопасным». Інші варіанти в цьому питанні («Да, когда на встречу едет грузовик или автобус», «Нет, кроме как на дорогах типа 2+1» та «Нет, ехать по укрепленному участку обочины разрешается только в экстренных случаях») не відповідають цій вимозі й тому неправильні."}, {"num": 332, "text": "В случае движения по автостраде, разрешается ли выезжать на укрепленный участок обочины, чтобы позволить быстро едущему транспорту совершить обгон?", "topic": "Автомагістраль і тунелі", "options": ["Только если грузовик или автобус хочет совершить обгон.", "Нет, кроме как на дорогах типа 2+1.", "Да, временно, когда на укрепленному участке обочины нет никого и проезд по нему будет безопасным.", "Только при движении по двойной проезжей части."], "correct": 2, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Да, временно, когда на укрепленному участке обочины нет никого и проезд по нему будет безопасным». Інші варіанти в цьому питанні («Только если грузовик или автобус хочет совершить обгон», «Нет, кроме как на дорогах типа 2+1» та «Только при движении по двойной проезжей части») не відповідають цій вимозі й тому неправильні."}, {"num": 333, "text": "Каковы действия водителя в очереди на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Водителю следует сохранять свою позицию в очереди.", "Совершить обгон справа и двигаться к началу очереди при наличии достаточного пространства.", "Подать соответствующий сигнал, чтобы препятствовать обгону другими транспортными средствами.", "Совершить обгон слева и двигаться к началу очереди при наличии достаточного пространства."], "correct": 0, "expl": "У черзі на світлофорі водій повинен зберігати своє місце в порядку черги, а не намагатися випередити інших об'їздом.", "explSpecific": "Правильно — «Водителю следует сохранять свою позицию в очереди». Обгін черги зліва чи справа для просування вперед — небезпечний і неввічливий маневр; сигналізація, щоб завадити обгону іншими, не є стандартною чи коректною поведінкою в черзі."}, {"num": 334, "text": "Что делать водителю находясь за рулем автомобиля, которым он никогда ранее не управлял?", "topic": "Швидкісний режим", "options": ["Сначала двигаться с особой осторожностью и на более низкой скорости, пока водитель полностью не ознакомится с транспортным средством.", "Двигаться с обычной осторожностью, поскольку функции всех транспортных средств одинаковы.", "Ездить только в ночное время, пока водитель полностью не освоит транспортное средство.", "Ехать быстрее обычного, чтобы иметь возможность оценить мощность автомобиля."], "correct": 0, "expl": "Керуючи незнайомим автомобілем уперше, водій повинен спершу їхати особливо обережно й повільніше, доки не звикне до особливостей керування саме цим транспортним засобом.", "explSpecific": "Правильно — «Сначала двигаться с особой осторожностью и на более низкой скорости, пока водитель полностью не ознакомится с транспортным средством». Припущення, що всі автомобілі керуються однаково, чи їзда лише вночі — необґрунтовані підходи; швидша їзда для «оцінки потужності» прямо суперечить обережності."}, {"num": 335, "text": "Что делать водителю на подъезде к участку дорожных работ с участием землеройной техники.", "topic": "Паркування та зупинка", "options": ["Снизить скорость, поскольку на дороги может остаться грязь и щебень.", "Включить фары для предупреждения и продолжать движение.", "Остановиться, развернуть автомобиль и найти альтернативный путь.", "Посигналить и продолжить движение на обычной скорости."], "correct": 0, "expl": "Наближаючись до ділянки робіт із землерийною технікою, водій повинен знизити швидкість, оскільки на дорозі могла залишитися грязь чи щебінь, що знижує зчеплення.", "explSpecific": "Правильно — «Снизить скорость, поскольку на дороги может остаться грязь и щебень». Просте вмикання фар без зниження швидкості, розворот в пошуках об'їзду чи сигнал із продовженням звичайної швидкості — недостатньо обережні реакції."}, {"num": 336, "text": "Учитывая скоростные ограничения, какова самая безопасная скорость движения транспортного средства?", "topic": "Швидкісний режим", "options": ["Скорость самого медленного автомобиля на дороге.", "Водитель должен всегда пытаться двигаться со скоростью других участников дорожного движения, независимо от ограничения скорости.", "Водитель всегда должен пытаться двигаться с постоянной скоростью.", "Скорость, которая позволит водителю остановить транспортное средство на достаточном расстоянии, позволяющем четко видеть участок дороги впереди."], "correct": 3, "expl": "Найбезпечніша швидкість — не фіксоване число, а та, що дозволяє зупинитися в межах дистанції, яку водій реально бачить попереду, незалежно від встановленого обмеження.", "explSpecific": "Правильно — «Скорость, которая позволит водителю остановить транспортное средство на достаточном расстоянии, позволяющем четко видеть участок дороги впереди». Рівняння на найповільніший транспорт чи підтримання постійної швидкості без урахування видимості — не є універсально безпечним підходом."}, {"num": 337, "text": "Если не указано иное, каков максимальный скоростной предел для автомобилей с автоприцепом на автострадах?", "topic": "Швидкісний режим", "options": ["120 км\\ч.", "60 км\\ч.", "80 км\\ч.", "100 км\\ч."], "correct": 2, "expl": "Для автомобіля з причепом на автостраді діє знижена межа швидкості порівняно зі звичайним автомобілем без причепа, через довшу гальмівну дистанцію та складнішу керованість.", "explSpecific": "Правильно — «80 км/ч». Це знижене обмеження саме для транспорту з причепом; 100 і 120 км/ч стосуються звичайних автомобілів без причепа, а 60 км/ч — надто занижена цифра."}, {"num": 338, "text": "Если не указано иное, каков максимальный скоростной предел для автомобилей с автоприцепом на автомагистрали?", "topic": "Швидкісний режим", "options": ["60 км\\ч.", "120 км\\ч.", "80 км\\ч.", "100 км\\ч."], "correct": 2, "expl": "На автомагістралі для транспорту з причепом діє знижена межа швидкості порівняно зі звичайним автомобілем без причепа.", "explSpecific": "Правильно — «80 км/ч» на автомагістралі для авто з причепом. «100» і «120 км/ч» стосуються звичайних автомобілів без причепа; «60 км/ч» — надто занижена цифра."}, {"num": 339, "text": "Что делать водителю, если другое транспортное средство блокирует его право проезда на перекрестке?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Запастись терпением и проявлять сдержанность.", "Подать звуковой сигнал и включить фары, чтобы показать свое разочарование.", "Следовать за транспортным средством и выразить свое недовольство.", "Моргнуть фарами и выразить свое недовольство."], "correct": 0, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Запастись терпением и проявлять сдержанность». Інші варіанти в цьому питанні («Подать звуковой сигнал и включить фары, чтобы показать свое разочарование», «Следовать за транспортным средством и выразить свое недовольство» та «Моргнуть фарами и выразить свое недовольство») не відповідають цій вимозі й тому неправильні."}, {"num": 340, "text": "Водитель, отправляющийся в поездку, расстроен или обозлен. Как ему следует действовать?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Расстройство или злость водителя не влияет на управление автомобилем.", "Ехать медленнее, чем обычно, чтобы сохранить соответствующее расстояние.", "Ехать быстрее, чем обычно, чтобы сохранить соответствующее расстояние.", "Водитель не должен отправляться в поездку, пока не успокоится."], "correct": 3, "expl": "Емоційний стан — засмучення чи злість — суттєво впливає на концентрацію й прийняття рішень за кермом, тому в такому стані краще відкласти поїздку.", "explSpecific": "Правильно — «Водитель не должен отправляться в поездку, пока не успокоится». Твердження, що емоції не впливають на керування, — небезпечна помилка; зміна швидкості не вирішує кореневу проблему втраченої концентрації."}, {"num": 341, "text": "Как водителю следует действовать в случае обгона при наличии встречного транспорта?", "topic": "Обгін та зміна смуги руху", "options": ["Позволить обгоняющему транспортному средству проехать и безопасным образом вернуться на левую сторону дороги.", "Ускориться так, чтобы следующее за вами транспортное средство не смогло совершить обгон.", "Сохранить позицию и включить фары, чтобы предупредить встречный транспорт.", "Сохранить позицию, поскольку другие водители не должны пытаться совершить обгон."], "correct": 0, "expl": "Якщо вас обганяють за наявності зустрічного транспорту, найправильніше — дозволити обгонному авто завершити маневр і безпечно повернутися на свій бік дороги.", "explSpecific": "Правильно — «Позволить обгоняющему транспортному средству проехать и безопасным образом вернуться на левую сторону дороги». Прискорення, щоб завадити обгону, чи миготіння фарами — небезпечні, агресивні реакції."}, {"num": 342, "text": "Что следует делать водителю, если другой водитель в спешке подрезает его спереди.", "topic": "Погодні умови та видимість", "options": ["Ехать быстрее, чтобы наверстать упущенное время.", "Моргнуть фарами и выразить свое недовольство.", "Ехать непосредственно за ними, чтобы другие транспортные средства не могли сделать то же самое.", "Запастись терпением и проявить сдержанность."], "correct": 3, "expl": "Якщо інший водій різко підрізав вас, найправильніша реакція — зберегти спокій і терпіння, а не відповідати агресією чи ризикованими діями.", "explSpecific": "Правильно — «Запастись терпением и проявить сдержанность». Прискорення, миготіння фарами чи їзда впритул за порушником — усе це форми агресивної відповіді, які підвищують ризик."}, {"num": 343, "text": "Что делать водителю, в случае прокола шин во время движения?", "topic": "Автомагістраль і тунелі", "options": ["Продолжать движение, пока не найдет подходящее место для остановки и ремонта", "Сохранять скорость, пока не найдет подходящее место для замены колеса.", "Остановиться в безопасном месте и заменить колесо.", "Если он находится на автомагистрали, немедленно остановиться и заменить колесо."], "correct": 2, "expl": "На автомагістралі і в тунелі головні ризики — це висока швидкість потоку і обмежені можливості для зупинки чи розвороту. Тому правила вимагають додаткової підготовки заздалегідь (перевірка пального, справності авто), підтримання дистанції пропорційної швидкості, і чітких дій у разі затору чи поломки — увімкнути аварійну сигналізацію, за можливості з'їхати на узбіччя чи в аварійну нішу, і не залишатись у смузі руху.", "explSpecific": "Порівняй формулювання: правильна відповідь передбачає дію «Остановиться в безопасном месте и заменить колесо», а один із неправильних варіантів пропонує протилежне — «Продолжать движение, пока не найдет подходящее место для остановки и ремонта». Це невипадково: у ситуації невизначеності чи небезпеки пріоритет — зупинитись, а не продовжувати рух як зазвичай."}, {"num": 344, "text": "Что делать водителю, если он хочет перестроиться на правую полосу, по которой движутся другие транспортные средства?", "topic": "Обгін та зміна смуги руху", "options": ["Притормозить и остановиться, дождаться подходящего зазора, а затем перестроиться на правую полосу.", "Посмотреть в зеркало, подать соответствующий сигнал и перестроиться на правую полосу, когда появится соответствующий зазор.", "Увеличить скорость до скорости транспортных средств, движущихся по этой полосе, затем перестроиться и посмотреть в зеркала.", "Постепенно перестроиться на правую полосу, подать соответствующий сигнал и посмотреть в зеркала."], "correct": 1, "expl": "Перестроюючись на праву смугу, водій повинен дотримуватися стандартної послідовності: подивитися в дзеркало, подати сигнал і перестроїтися, коли з'явиться безпечний проміжок.", "explSpecific": "Правильно — «Посмотреть в зеркало, подать соответствующий сигнал и перестроиться на правую полосу, когда появится соответствующий зазор». Зупинка в очікуванні чи прискорення ПЕРЕД сигналом порушують правильний порядок дій."}, {"num": 345, "text": "Какое действие оказывает алкоголь на поведение водителя?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Он замедляет реакцию водителя.", "Под действием алкоголя водитель становится более сосредоточенным.", "Алкоголь ускоряет реакцию водителя.", "Придает водителю уверенность."], "correct": 0, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Он замедляет реакцию водителя». Інші варіанти в цьому питанні («Под действием алкоголя водитель становится более сосредоточенным», «Алкоголь ускоряет реакцию водителя» та «Придает водителю уверенность») не відповідають цій вимозі й тому неправильні."}, {"num": 346, "text": "Если автомобилист или мотоциклист принимает лекарственный препарат, который может повлиять на вождение, что ему следует делать?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Находясь под воздействием лекарственных препаратов, влияющих на вождение, ему следует ехать медленнее.", "Выезжать только на короткие расстояния.", "Обратиться к лечащему врачу за консультацией по поводу безопасности вождения.", "Пить большое количество жидкости во время вождения."], "correct": 2, "expl": "Якщо ліки можуть вплинути на здатність керувати автомобілем, водій повинен проконсультуватися з лікарем щодо безпеки водіння, а не самостійно вирішувати, як компенсувати вплив препарату.", "explSpecific": "Правильно — «Обратиться к лечащему врачу за консультацией по поводу безопасности вождения». Просто повільніша їзда, короткі поїздки чи вживання великої кількості рідини — не є медично обґрунтованими способами компенсувати вплив ліків."}, {"num": 347, "text": "Согласно Отчету о ДТП, какой пол более склонен к вождению в нетрезвом виде, которое влекло за собой столкновение со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Количество мужчины и женщин, садящихся за руль в нетрезвом виде, одинаково.", "Женщины", "Ни мужчины, ни женщины не садятся за руль в нетрезвом виде.", "Мужчины."], "correct": 3, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Мужчины». Інші варіанти в цьому питанні («Количество мужчины и женщин, садящихся за руль в нетрезвом виде, одинаково», «Женщины» та «Ни мужчины, ни женщины не садятся за руль в нетрезвом виде») не відповідають цій вимозі й тому неправильні."}, {"num": 348, "text": "Как влияет влажное дорожное покрытие на торможение транспортного средства?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Оно никак не влияет на требуемый тормозной путь.", "Современные шины обеспечивают одинаковое сцепление как на мокрой, так и на сухой дорожной поверхности.", "Как правило, оно удваивает тормозной путь, который требуется на сухой поверхности.", "Как правило, оно снижает тормозной путь, который требуется на сухой поверхности."], "correct": 2, "expl": "Волога дорожня поверхня суттєво знижує коефіцієнт зчеплення шин з асфальтом, тому загальне практичне правило — гальмівний шлях на мокрій дорозі приблизно вдвічі довший, ніж на сухій.", "explSpecific": "Правильно — «Как правило, оно удваивает тормозной путь». «Ніяк не впливає» і «сучасні шини забезпечують однакове зчеплення» прямо суперечать фізиці зниженого зчеплення на мокрій поверхні; «зменшує гальмівний шлях» — протилежний, невірний висновок."}, {"num": 349, "text": "Что произойдет, если водитель слишком рано подрежет другое транспортное средство при обгоне?", "topic": "Обгін та зміна смуги руху", "options": ["Водителю не следует подавать никаких знаков в этом случае.", "Это заставит другое транспортное средство внезапно замедлиться или изменить направление, вызывая опасность.", "Это заставит встречные транспортные внезапно замедлить движение, что создаст опасность.", "Безопасный зазор между транспортными средствами увеличится."], "correct": 1, "expl": "Якщо водій підрізає обганюваний транспорт занадто рано, це змушує того водія раптово гальмувати чи маневрувати, створюючи небезпеку.", "explSpecific": "Правильно — «Это заставит другое транспортное средство внезапно замедлиться или изменить направление, вызывая опасность». Твердження про відсутність сигналів чи вплив на зустрічний транспорт не описують реальний наслідок."}, {"num": 350, "text": "Что должен сделать водитель после обгона другого транспортного средства?", "topic": "Обгін та зміна смуги руху", "options": ["Сразу сдвинуться влево при обгоне другого транспортного средства.", "Продолжать подавать сигнал о необходимости дополнительного расстояния.", "Постепенно съехать влево, после обгона транспортного средства.", "Отъехать назад перед автомобилем и снизить скорость."], "correct": 2, "expl": "Після завершення обгону водій повинен плавно повернутися на свою (ліву) смугу, переконавшись у достатній дистанції до обігнаного транспорту.", "explSpecific": "Правильно — «Постепенно съехать влево, после обгона транспортного средства». Різкий поворот ліворуч під час самого обгону небезпечний; продовження сигналізації про потребу простору не відповідає правильному завершенню маневру."}, {"num": 351, "text": "Согласно Отчету о ДТП, причиной скольких столкновений со смертельным исходом послужило алкогольное опьянение?", "topic": "Алкоголь, наркотики, втома водія", "options": ["46% и более.", "От 31 до 45%.", "От 16 до 30%.", "От 1 до 15%."], "correct": 1, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «От 31 до 45%». Інші варіанти в цьому питанні («46% и более», «От 16 до 30%» та «От 1 до 15%») не відповідають цій вимозі й тому неправильні."}, {"num": 352, "text": "Что следует делать водителю при объезде припаркованных транспортных средств в жилом районе?", "topic": "Паркування та зупинка", "options": ["Держаться поближе к припаркованным транспортным средствам, оставляя максимум места для движения встречных транспортных средств.", "Обеспечить достаточный зазор при проезде.", "Двигаться как можно правее.", "Увеличить скорость, чтобы как можно быстрее объехать эти автомобили."], "correct": 1, "expl": "Об'їжджаючи припарковані автомобілі в житловому районі, водій повинен забезпечити достатній бічний проміжок, оскільки будь-які двері можуть несподівано відчинитися.", "explSpecific": "Правильно — «Обеспечить достаточный зазор при проезде». Триматися впритул до припаркованих авто чи рухатися максимально праворуч без потреби — небезпечні крайнощі; збільшення швидкості для швидшого проїзду підвищує ризик."}, {"num": 353, "text": "На каком расстоянии обычно следует проезжать мимо припаркованных транспортных средств?", "topic": "Паркування та зупинка", "options": ["На расстоянии, равном ширине бокового зеркала.", "На расстоянии, равном ширине автомобиля.", "На расстоянии, равном ширине двери автомобиля.", "На расстоянии, равном ширине среднестатистического человека."], "correct": 2, "expl": "Загальна рекомендація — проїжджати повз припарковані автомобілі на відстані, приблизно рівній ширині відчинених дверей, щоб уникнути зіткнення з раптово відчиненими дверима.", "explSpecific": "Правильно — «На расстоянии, равном ширине двери автомобиля». Ширина бокового дзеркала чи людини — надто малі орієнтири; ширина цілого автомобіля — надмірна й непрактична вимога для звичайної вулиці."}, {"num": 354, "text": "Какой тормозной путь водитель должен учитывать при движении по снегу или в условиях гололеда?", "topic": "Погодні умови та видимість", "options": ["До половины обычного расстояния.", "Обычное расстояние.", "До десяти раз больше обычного расстояния.", "В два раза больше обычного расстояния."], "correct": 2, "expl": "На снігу чи ожеледиці зчеплення шин з дорогою може знижуватися настільки сильно, що гальмівний шлях зростає в рази — до десяти разів довше звичайного.", "explSpecific": "Правильно — «До десяти раз больше обычного расстояния». Менші оцінки суттєво недооцінюють реальну небезпеку екстремально слизьких умов."}, {"num": 355, "text": "Почему автомобилю нужно больше времени для остановки на влажной дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Сцепление шин с мокрой дорожной поверхностью меньше, чем с сухой.", "Подвеска автомобиля становится легче в сырую погоду.", "Тормозная жидкость менее эффективна в сырую погоду.", "Сцепление шин с мокрой дорожной поверхностью больше, чем с сухой."], "correct": 0, "expl": "Причина довшого гальмівного шляху на мокрій дорозі — саме нижчий коефіцієнт зчеплення шин із вологим покриттям порівняно з сухим.", "explSpecific": "Правильно — «Сцепление шин с мокрой дорожной поверхностью меньше, чем с сухой». «Підвіска стає легшою» і «гальмівна рідина менш ефективна у вологу погоду» — вигадані твердження; «зчеплення більше на мокрій» — прямо протилежний, невірний висновок."}, {"num": 356, "text": "Каково влияние на управление автомобилем оказывает водной слой межу шинами транспортного средства и дорожной поверхностью?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Рулевое управление будет более эффективным.", "Рулевое управление и торможение будут более эффективными.", "Только торможение будут менее эффективными.", "Рулевое управление и торможение будут менее эффективными."], "correct": 3, "expl": "Шар води між шиною і дорогою (аквапланування) фізично відриває шину від контакту з покриттям, тому одночасно погіршуються і кермування, і гальмування.", "explSpecific": "Правильно — «Рулевое управление и торможение будут менее эффективными» — уражені обидві системи одночасно. Твердження про покращення чи вибіркове погіршення лише гальмування суперечать самій суті втрати контакту шини з дорогою."}, {"num": 357, "text": "Что должен делать водитель если на дороге мелкий щебень?", "topic": "Паркування та зупинка", "options": ["Замедлится и обеспечить дополнительное пространство для другого транспорта.", "Остановить автомобиль и дождаться, пока щебень не удалят с поверхности дороги.", "Водитель должен прижать руку к ветровому стеклу.", "Увеличить скорость, чтобы не повредить автомобиль."], "correct": 0, "expl": "Побачивши дрібний щебінь на дорозі, водій повинен сповільнитися й дати додатковий простір іншому транспорту, оскільки щебінь може вилітати з-під коліс.", "explSpecific": "Правильно — «Замедлится и обеспечить дополнительное пространство для другого транспорта». Повна зупинка в очікуванні прибирання щебеню чи притискання руки до скла — недоречні реакції; збільшення швидкості підвищує ризик пошкодження."}, {"num": 358, "text": "Какое влияние оказывают пятна масла или дизельного топлива на дорожное покрытие?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Улучшает сцепление с поверхностью шины.", "Улучшает тормозную способность автомобиля.", "Увеличивает шум на поверхности шин.", "Уменьшает сцепление поверхности шины"], "correct": 3, "expl": "Плями оливи чи дизпалива на асфальті створюють тонку слизьку плівку, яка суттєво знижує зчеплення шини з дорогою — подібно до ефекту льоду чи води.", "explSpecific": "Правильно — «Уменьшает сцепление поверхности шины». Варіанти про покращення зчеплення чи гальмування прямо суперечать фізичному ефекту мастила; «збільшує шум» не є характерним чи значущим наслідком плям оливи."}, {"num": 359, "text": "Что следует делать водителю при движении по скользкой дороге?", "topic": "Погодні умови та видимість", "options": ["Двигаться на более низких скоростях и использовать плавное ускорение и торможение.", "Время от времени резко тормозить, чтобы проверить сцепление с поверхностью дороги.", "Соблюдать нормальное расстояние от впереди идущего автомобиля.", "Двигаться с обычной скоростью, но обеспечить дополнительный тормозной путь."], "correct": 0, "expl": "На слизькій дорозі головне правило — рухатися повільніше і плавно, без різких прискорень чи гальмувань, які легко провокують занос.", "explSpecific": "Правильно — «Двигаться на более низких скоростях и использовать плавное ускорение и торможение». Періодичне різке гальмування «для перевірки» зчеплення — небезпечна порада; звичайна дистанція чи швидкість недостатньо обережні для слизької поверхні."}, {"num": 360, "text": "Какой штраф предусмотрен за вождение в нетрезвом состоянии для водителя-ученика при концентрации алкоголя в крови (ВАС) от 20 до 80 мг на 100 миллилитров крови?", "topic": "Штрафні бали, права та документи", "options": ["Штраф в размере 200 евро и лишение водительских прав на 3 месяца.", "Штраф в размере 200 евро и лишение водительских прав на 6 месяца.", "Штраф в размере 200 евро и 3 штрафных пункта.", "Штраф в размере 200 евро и 5 штрафных пунктов"], "correct": 0, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Штраф в размере 200 евро и лишение водительских прав на 3 месяца». Інші варіанти в цьому питанні («Штраф в размере 200 евро и лишение водительских прав на 6 месяца», «Штраф в размере 200 евро и 3 штрафных пункта» та «Штраф в размере 200 евро и 5 штрафных пунктов») не відповідають цій вимозі й тому неправильні."}, {"num": 361, "text": "Как вождение на высокой скорости влияет на сцепление автомобиля с дорогой?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Удерживающая способность автомобиля увеличивается.", "Удерживающая способность автомобиля уменьшается.", "Выравнивание колес удерживает шины в полном контакте с дорожной поверхностью.", "Подвеска компенсирует любые неровности дорожной поверхности."], "correct": 1, "expl": "На високій швидкості шини мають менше часу контакту з нерівностями дороги, через що зчеплення (утримувальна здатність) автомобіля з дорогою знижується.", "explSpecific": "Правильно — «Удерживающая способность автомобиля уменьшается». «Збільшується» — прямо протилежний, невірний висновок; твердження про розвал коліс чи підвіску, що компенсує нерівності, не мають стосунку до впливу саме швидкості на зчеплення."}, {"num": 362, "text": "Какой штраф предусмотрен за вождение в нетрезвом состоянии для профессионального водителя при концентрации алкоголя в крови (BAC) от 20 до 80 мг на 100 миллилитров крови?", "topic": "Штрафні бали, права та документи", "options": ["Штраф в размере 200 евро и лишение водительских прав на 3 месяцев.", "При концентрации алкоголя ниже 50 мг (BAC) штраф не предусмотрен.", "Штраф применяется только при концентрации свыше 80 мг (BAC).", "Штраф в размере 100 евро и лишение водительских прав на 6 месяцев."], "correct": 0, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Тут усі варіанти відрізняються переважно конкретним числовим значенням — це питання на запам'ятовування точного нормативу, а не на логіку. Правильне значення саме таке, яке вказано у правильній відповіді; інші цифри в цьому питанні — невірні нормативи, які варто не переплутати."}, {"num": 363, "text": "Каковы вероятные последствия резкого торможения?", "topic": "Обгін та зміна смуги руху", "options": ["Не будет никаких последствий, поскольку загорятся стоп-сигналы автомобиля.", "В автомобиль сзади может удариться другой автомобиль.", "Тормозная система автомобиля может перегреться.", "Может произойти обгон автомобиля."], "correct": 1, "expl": "Різке гальмування підвищує ризик, що транспорт позаду не встигне вчасно зупинитися і врізається у ваш автомобіль ззаду.", "explSpecific": "Правильно — «В автомобиль сзади может удариться другой автомобиль». Твердження про відсутність наслідків через стоп-сигнали недооцінює реальний ризик; перегрів гальмівної системи не є типовим прямим наслідком одного різкого гальмування."}, {"num": 364, "text": "Что влияет на тормозной путь автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Скорость и вес транспортного средства.", "Качество бензина.", "Марка тормозной жидкости.", "Марка автомобиля."], "correct": 0, "expl": "Гальмівний шлях фізично залежить передусім від швидкості руху (квадратична залежність) і маси транспортного засобу — саме ці два фактори визначають, скільки енергії потрібно погасити гальмами.", "explSpecific": "Правильно — «Скорость и вес транспортного средства». Якість бензину, марка гальмівної рідини чи марка автомобіля не є визначальними фізичними факторами гальмівного шляху."}, {"num": 365, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 50 км / ч по сухой дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["55 метров.", "25 метров.", "15 метров.", "5 метров."], "correct": 1, "expl": "Мінімальний рекомендований гальмівний шлях зростає зі швидкістю нелінійно; офіційна ірландська таблиця для сухої дороги на швидкості 50 км/год визначає орієнтовну мінімальну відстань саме в 25 метрів.", "explSpecific": "Правильно — «25 метров», згідно з офіційною таблицею гальмівних шляхів. Інші числа (5, 15, 55 метрів) не відповідають встановленому офіційному значенню для цієї швидкості й типу покриття."}, {"num": 366, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 50 км / ч по влажной дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["56 метров.", "36 метров.", "76 метров.", "16 метров."], "correct": 1, "expl": "На вологій дорозі мінімальний рекомендований гальмівний шлях на тій самій швидкості довший, ніж на сухій, через знижене зчеплення шин.", "explSpecific": "Правильно — «36 метров», згідно з офіційною таблицею гальмівних шляхів для вологої дороги на швидкості 50 км/год. Інші числа не відповідають встановленому офіційному значенню."}, {"num": 367, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 100 км / ч по сухой дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["70 метров.", "120 метров.", "90 метров.", "30 метров."], "correct": 0, "expl": "На вдвічі вищій швидкості (100 км/год замість 50) гальмівний шлях зростає значно більше, ніж удвічі, оскільки кінетична енергія авто зростає пропорційно квадрату швидкості.", "explSpecific": "Правильно — «70 метров», згідно з офіційною таблицею гальмівних шляхів для сухої дороги на швидкості 100 км/год. Інші числа не відповідають встановленому офіційному значенню."}, {"num": 368, "text": "Каков минимальный тормозной путь автомобиля или мотоцикла, движущегося со скоростью 100 км/ч по мокрой дороге?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["122 метра.", "80 метров.", "150 метров.", "200 метров."], "correct": 0, "expl": "На мокрій дорозі при швидкості 100 км/год мінімальний гальмівний шлях автомобіля чи мотоцикла суттєво довший, ніж на сухій — офіційне значення становить 122 метри.", "explSpecific": "Правильно — «122 метра», згідно з офіційною таблицею гальмівних шляхів. Інші числа (80, 150, 200 метрів) не відповідають встановленому офіційному значенню."}, {"num": 369, "text": "В сухую погоду, как водитель может оценить безопасное расстояние до автомобиля, следующего впереди?", "topic": "Швидкісний режим", "options": ["Обеспечив, по крайней мере, две длины транспортного средства между автомобилями.", "Используя фиксированную точку и применяя правило двух секунд.", "Двигаться с той же скоростью, что и транспортное средство, следующее впереди.", "Обеспечить как минимум две длины автомобиля на каждый километр в час."], "correct": 1, "expl": "У суху погоду безпечну дистанцію найкраще оцінювати за фіксованою точкою на дорозі й правилом двох секунд, а не довжинами автомобіля чи умовною однаковою швидкістю.", "explSpecific": "Правильно — «Используя фиксированную точку и применяя правило двух секунд». Довжини транспортного засобу — менш точний і не рекомендований офіційно метод; рух з тією ж швидкістю, що й транспорт попереду, сам по собі не гарантує безпечної дистанції."}, {"num": 370, "text": "В сырую погоду, как следует оценить безопасное расстояние до автомобиля, следующего впереди?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, должно составлять не менее 4 секунд.", "Время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, должно составлять не менее 4 метров.", "Время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, должно составлять не менее 6 метров.", "Время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, должно составлять не менее 2 секунд."], "correct": 0, "expl": "У вологу погоду рекомендована безпечна дистанція вимірюється часом проходження фіксованої точки — не менше 4 секунд, вдвічі більше за стандартні 2 секунди на сухій дорозі.", "explSpecific": "Правильно — «не менее 4 секунд». Вимірювання дистанції в метрах не відповідає рекомендованому часовому методу оцінки; «2 секунди» — норма для сухої дороги, недостатня для вологої."}, {"num": 371, "text": "Какая фраза помогает водителям определить безопасное расстояние от транспортного средства, следующего впереди по сухой дороге.", "topic": "Загальні правила та поведінка на дорозі", "options": ["\"Только дурак нарушает правило одной секунды\".", "\"Только дурак нарушает правило четырех секунд\".", "\"Только дурак нарушает правило двух секунд\".", "\"Только дурак нарушает правило трех секунд\"."], "correct": 2, "expl": "Класична мнемонічна фраза для оцінки безпечної дистанції на сухій дорозі — «тільки дурень порушує правило двох секунд», яка нагадує про мінімальний часовий інтервал до автомобіля попереду.", "explSpecific": "Правильно — «Только дурак нарушает правило двух секунд». Варіанти з одна, три чи чотири секундами не відповідають усталеній версії цієї фрази саме для сухої дороги (4 секунди — це вже для вологої, за іншим правилом)."}, {"num": 372, "text": "Как влияет груз на торможение транспортного средства?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Он уменьшает расстояние, необходимое для остановки.", "Он увеличивает эффективность тормозов.", "Он увеличивает расстояние, необходимое для остановки.", "Он не оказывает никакого влияния, если тормоза исправны."], "correct": 2, "expl": "Додатковий вантаж збільшує загальну масу транспортного засобу, а отже, і кінетичну енергію, яку потрібно погасити гальмами — тому гальмівний шлях зростає.", "explSpecific": "Правильно — «Он увеличивает расстояние, необходимое для остановки». «Зменшує» і «підвищує ефективність гальм» прямо суперечать фізиці ваги; «не впливає, якщо гальма справні» ігнорує фундаментальний вплив маси на гальмівний шлях."}, {"num": 373, "text": "Как влияет буксировка загруженного прицепа на тормозную способность?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Она сокращает тормозной путь.", "Она увеличивает эффективность тормозов.", "Она не оказывает никакого влияния на тормозной путь.", "Она увеличивает тормозной путь."], "correct": 3, "expl": "Великогабаритний транспорт і техніка з причепом мають більшу масу, довший гальмівний шлях, більші сліпі зони та вищий ризик перекидання на поворотах чи нерівностях. Тому логіка тут — рухатися повільніше, забезпечувати більшу дистанцію та бути особливо обережним на кільцевих розв'язках і поворотах, де причіп може «зрізати» траєкторію. Це пояснює, чому правильні відповіді часто пов'язані зі зниженням швидкості або додатковою перевіркою перед маневром.", "explSpecific": "Правильна відповідь тут — «Она увеличивает тормозной путь». Інші варіанти в цьому питанні («Она сокращает тормозной путь», «Она увеличивает эффективность тормозов» та «Она не оказывает никакого влияния на тормозной путь») не відповідають цій вимозі й тому неправильні."}, {"num": 374, "text": "Какой свет фар следует использовать водителю в густом тумане?", "topic": "Погодні умови та видимість", "options": ["Ехать с включенными фарами ближнего света и противотуманными фарами.", "Ехать с включенными габаритными фарами и аварийными огнями.", "Ехать с включенными габаритными и противотуманными фарами.", "Ехать с включенными фарами дальнего света и противотуманными фарами."], "correct": 0, "expl": "У густому тумані оптимальна комбінація освітлення — фари ближнього світла разом із протитуманними фарами.", "explSpecific": "Правильно — «...ближнего света и противотуманными фарами». Габаритні вогні чи аварійні сигнали недостатньо яскраві для освітлення дороги; дальнє світло в тумані відбивається назад, засліплюючи самого водія."}, {"num": 375, "text": "Как должен действовать водитель при езде в густом тумане?", "topic": "Погодні умови та видимість", "options": ["Снизить скорость и включить фары ближнего света.", "Ехать вдоль укрепленной части обочины и следить за отражающими маркерами.", "Снизить скорость и включить фары дальнего света.", "Ехать вдоль центральной разделительной линии и следить за отражающими маркерами."], "correct": 0, "expl": "У густому тумані водій повинен знизити швидкість і використовувати фари ближнього світла — базові дії безпеки в умовах різко обмеженої видимості.", "explSpecific": "Правильно — «Снизить скорость и включить фары ближнего света». Дальнє світло в тумані погіршує власну видимість через відбиття; орієнтування по узбіччю чи центральній лінії не є основною рекомендованою дією."}, {"num": 376, "text": "На каком расстоянии должен видеть водитель при ночной езде с включенными фарами дальнего света типичного автомобиля?", "topic": "Погодні умови та видимість", "options": ["150 метров.", "100 метров.", "200 метров.", "50 метров."], "correct": 1, "expl": "Фари дальнього світла типового автомобіля повинні забезпечувати водієві видимість дороги на відстані щонайменше 100 метрів уночі.", "explSpecific": "Правильно — «100 метров» — стандартний показник для дальнього світла. Інші числа (50, 150, 200 метрів) не відповідають встановленому орієнтовному значенню."}, {"num": 377, "text": "На каком расстоянии должен видеть водитель при ночной езде с включенными фарами ближнего света типичного автомобиля?", "topic": "Погодні умови та видимість", "options": ["20 метров.", "40 метров.", "50 метров.", "30 метров."], "correct": 3, "expl": "Фари ближнього світла забезпечують меншу дальність освітлення, ніж дальнє світло — орієнтовно 30 метрів, достатньо для безпечного руху в населених пунктах.", "explSpecific": "Правильно — «30 метров». Інші числа (20, 40, 50 метрів) не відповідають встановленому орієнтовному значенню саме для ближнього світла."}, {"num": 378, "text": "Каковы возможные последствия неправильной регулировки фар?", "topic": "Погодні умови та видимість", "options": ["Мощность фа можно быть уменьшена.", "Видимость может быть увеличена.", "Фары могут перегреться.", "Можно ослепить водителей встречного транспорта."], "correct": 3, "expl": "Неправильно відрегульовані фари можуть світити занадто високо, засліплюючи водіїв зустрічного транспорту, замість освітлювати дорогу перед собою.", "explSpecific": "Правильно — «Можно ослепить водителей встречного транспорта». Твердження про зменшену потужність, збільшену видимість чи перегрів ламп не є типовими наслідками саме неправильного регулювання кута світла."}, {"num": 379, "text": "При движении ночью, когда водитель должен приглушить дальний свет фар автомобиля?", "topic": "Погодні умови та видимість", "options": ["При въезде на автомагистраль.", "Когда нет встречного движения.", "При движении со скоростью менее 50 км/ч.", "При встречном транспорте или движении за другим транспортным средством."], "correct": 3, "expl": "Дальнє світло потрібно приглушувати (перемикати на ближнє), щойно з'являється зустрічний транспорт або водій наближається до транспорту попереду, щоб не засліпити інших.", "explSpecific": "Правильно — «При встречном транспорте или движении за другим транспортным средством». В'їзд на автомагістраль чи низька швидкість самі по собі не вимагають перемикання світла; «коли немає зустрічного руху» — це умова, за якої дальнє світло МОЖНА використовувати."}, {"num": 380, "text": "При движении ночью, когда водитель должен приглушить дальний свет фар автомобиля?", "topic": "Погодні умови та видимість", "options": ["При въезде на автомагистраль.", "Когда нет встречного движения.", "При движении со скоростью менее 50 км/ч.", "При встречном транспорте или движении за другим транспортным средством."], "correct": 3, "expl": "Дальнє світло потрібно приглушувати, щойно з'являється зустрічний транспорт або водій наближається до транспорту попереду, щоб не засліпити інших.", "explSpecific": "Правильно — «При встречном транспорте или движении за другим транспортным средством». В'їзд на автомагістраль чи низька швидкість не вимагають перемикання світла; «коли немає зустрічного руху» — умова, за якої дальнє світло можна використовувати."}, {"num": 381, "text": "Какие фары должен включить водитель, когда он едет позади другого транспортного средства в ночное время?", "topic": "Погодні умови та видимість", "options": ["Передние противотуманные фары.", "Фары дальнего света.", "Фары ближнего света.", "Габаритные фонари."], "correct": 2, "expl": "Рухаючись позаду іншого транспортного засобу вночі, водій повинен використовувати фари ближнього світла, щоб не засліплювати водія попереду через дзеркала заднього виду.", "explSpecific": "Правильно — «Фары ближнего света». Дальнє світло засліпить водія попереду через дзеркала; протитуманні фари призначені для туману; самі лише габаритні вогні недостатньо яскраві."}, {"num": 382, "text": "Водитель регулярно ездил при дневном свете и теперь должен отправиться в поездку ночью. Как водителю следует поступить?", "topic": "Погодні умови та видимість", "options": ["Двигаться с более высокой скоростью, чем в дневное время, так как ночью меньше транспорта.", "Двигаться с более высокой скоростью, чем в дневное время, чтобы свести к минимуму вероятность засыпания.", "Двигаться медленнее, чем в дневное время, так как в ночное время видимость снижается.", "Ехать с той же скоростью, что и в дневное время, так как никакой дополнительной опасности нет."], "correct": 2, "expl": "Водієві, який звик їздити вдень, вночі слід рухатися повільніше, ніж вдень, оскільки видимість і час реакції на перешкоди вночі значно гірші.", "explSpecific": "Правильно — «Двигаться медленнее, чем в дневное время, так как в ночное время видимость снижается». Твердження про потребу їхати швидше прямо суперечать логіці зниженої видимості; «та сама швидкість, що і вдень» ігнорує реальну різницю умов."}, {"num": 383, "text": "Что касается скорости автомобиля, что должен делать водитель при движении ночью?", "topic": "Швидкісний режим", "options": ["Двигайтесь со скоростью, позволяющей водителю остановиться на расстоянии, позволяющем четко видеть участок дороги впереди.", "Увеличить скорость автомобиля, так как в ночное время двигаться легче.", "Сохранять нормальную скорость автомобиля и двигаться с полностью включенными фарами.", "Двигаться с более высокой скоростью, чем в дневное время, чтобы свести к минимуму вероятность засыпания."], "correct": 0, "expl": "Правила зупинки й парковки будуються навколо трьох речей: не створювати перешкоду для руху, не закривати огляд іншим учасникам (особливо на перехрестях і пішохідних переходах) і не наражати на небезпеку тих, хто виходить з машини. Тому заборонено зупинятись близько до перехрестя, на пішохідному переході, у місцях з подвійною жовтою лінією чи де це прямо заборонено знаком. Правильна відповідь зазвичай та, що залишає достатньо простору та видимості для інших.", "explSpecific": "Правильна відповідь тут — «Двигайтесь со скоростью, позволяющей водителю остановиться на расстоянии, позволяющем четко видеть участок дороги впереди». Інші варіанти в цьому питанні («Увеличить скорость автомобиля, так как в ночное время двигаться легче», «Сохранять нормальную скорость автомобиля и двигаться с полностью включенными фарами» та «Двигаться с более высокой скоростью, чем в дневное время, чтобы свести к минимуму вероятность засыпания») не відповідають цій вимозі й тому неправильні."}, {"num": 384, "text": "Какой самый безопасный способ езды ночью?", "topic": "Погодні умови та видимість", "options": ["Двигайтесь со скоростью, позволяющей водителю остановиться на расстоянии, позволяющем четко видеть участок дороги впереди.", "Всегда двигаться с включенными фарами дальнего света.", "Двигаться на максимальной скорости с постоянно включенным ближним светом фар.", "Двигаться на максимальной скорости с постоянно включенным дальним светом фар."], "correct": 0, "expl": "Найбезпечніший принцип нічної їзди — обирати швидкість, за якої водій встигне зупинитися в межах дистанції, яку він реально бачить попереду при своєму освітленні.", "explSpecific": "Правильно — «Двигайтесь со скоростью, позволяющей водителю остановиться на расстоянии, позволяющем четко видеть участок дороги впереди». Постійне використання дальнього чи ближнього світла на максимальній швидкості ігнорує головний принцип."}, {"num": 385, "text": "Что должен делать водитель увидев встречное транспортное средство в ночное время?", "topic": "Швидкісний режим", "options": ["Старайтесь не смотреть прямо на огни встречного автомобиля.", "Сосредоточье взгляд прямо на руле.", "Сосредоточье взгляд непосредственно на огнях встречного автомобиля.", "Увеличьте скорость, чтобы быстрее проехать мимо встречного автомобиля."], "correct": 0, "expl": "Побачивши зустрічний транспорт уночі, водій повинен уникати прямого погляду на його фари, щоб не втратити тимчасово зір.", "explSpecific": "Правильно — «Старайтесь не смотреть прямо на огни встречного автомобиля». Зосередження погляду на кермі чи прямо на фарах — неправильні й небезпечні техніки; збільшення швидкості, щоб швидше розминутися, підвищує ризик зіткнення."}, {"num": 386, "text": "Что должен делать водитель при движении ночью будучи ослепленным светом фар встречного автомобиля?", "topic": "Погодні умови та видимість", "options": ["Несколько раз моргните фарами, чтобы предупредить нарушающего водителя.", "Посмотреть в сторону и замедлить движение и остановиться, при необходимости.", "Снизить скорость и включить фары дальнего света.", "Переместиться влево и продолжать движение с нормальной скоростью."], "correct": 1, "expl": "Осліплений вночі фарами зустрічного авто водій повинен відвести погляд убік від джерела світла, знизити швидкість і за потреби зупинитися, доки зір не відновиться.", "explSpecific": "Правильно — «Посмотреть в сторону и замедлить движение и остановиться, при необходимости». Миготіння фарами у відповідь не вирішує проблему власної засліпленості; увімкнення дальнього світла чи зміщення ліворуч зі збереженням швидкості небезпечні."}, {"num": 387, "text": "Когда водитель может безопасно использовать фары дальнего света при движении в ночное время?", "topic": "Погодні умови та видимість", "options": ["В застроенных районах с хорошим уличным освещением.", "Такая практика не разрешена.", "Когда нет встречного движения.", "При следовании за транспортным средством, которое находится на небольшом расстоянии впереди."], "correct": 2, "expl": "Дальнє світло безпечно використовувати вночі лише тоді, коли немає зустрічного транспорту, який воно могло б засліпити.", "explSpecific": "Правильно — «Когда нет встречного движения». У забудованих районах з освітленням дальнє світло зазвичай не потрібне; «взагалі не дозволено» — надто категорично; рух за транспортом попереду вимагає ближнього світла."}, {"num": 388, "text": "О чем должен знать водитель во время вождения поздно ночью?", "topic": "Обгін та зміна смуги руху", "options": ["Все пешеходы носят светоотражающую одежду.", "Эти скоростные ограничения не применяются с полуночи до 6 часов утра.", "Эти грузовики могут проехать по внешней полосе автомагистрали.", "Существует опасность того, что заснет он сам или другие участники дорожного движения."], "correct": 3, "expl": "Керуючи автомобілем пізно вночі, водій повинен пам'ятати про підвищений ризик засинання за кермом — і власного, і інших учасників руху.", "explSpecific": "Правильно — «Существует опасность того, что заснет он сам или другие участники дорожного движения». Твердження про світловідбивний одяг усіх пішоходів чи скасування обмежень швидкості вночі — вигадані факти."}, {"num": 389, "text": "Что должен делать водитель будучи ослепленным светом фар встречного автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Прикрыть глаза рукой.", "Не смотреть прямо на огни.", "На мгновение взглянуть на приборную панель.", "Повернуть голову вправо."], "correct": 1, "expl": "Осліплений фарами зустрічного авто водій повинен уникати прямого погляду на джерело світла, щоб мінімізувати тимчасову втрату зору, і дивитися трохи вбік, на край своєї смуги.", "explSpecific": "Правильно — «Не смотреть прямо на огни». Прикриття очей рукою чи погляд на панель приладів небезпечно відволікають від дороги; поворот голови праворуч надто різкий та не є стандартною технікою."}, {"num": 390, "text": "Когда водитель должен использовать противотуманные фары на своем автомобиле?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Использовать противотуманные фары на плохо освещенной проселочной дороге.", "Включить противотуманные фары, чтобы предупредить пешеходов.", "Использовать противотуманные фары, чтобы улучшить видимость во время небольшого дождя.", "Использовать противотуманные фары только во время густого тумана или падающего снега."], "correct": 3, "expl": "Протитуманні фари призначені виключно для густого туману чи сильного снігопаду — їх не варто вмикати за інших обставин, навіть у поганому освітленні чи невеликому дощі.", "explSpecific": "Правильно — «Использовать противотуманные фары только во время густого тумана или падающего снега». Використання на погано освітленій дорозі чи для попередження пішоходів виходить за межі призначення протитуманних фар і може засліпити інших."}, {"num": 391, "text": "Когда образуется наледь (черный лед)?", "topic": "Погодні умови та видимість", "options": ["Наледь образуется только на автомагистралях.", "Только рано утром.", "Когда температура падает до отметки, близко к замерзанию.", "Только поздно ночью."], "correct": 2, "expl": "Ожеледиця (чорний лід) утворюється, коли температура повітря чи дорожнього покриття опускається близько до нуля градусів, незалежно від типу дороги чи часу доби.", "explSpecific": "Правильно — «Когда температура падает до отметки, близко к замерзанию». Прив'язка виключно до автомагістралей чи певної частини доби невиправдано звужує справжню, температурну причину утворення ожеледиці."}, {"num": 392, "text": "Каковы действия водителя в случае наледи на дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Регулярно притормаживать, чтобы тормоза не замерзли.", "Избегать резкого торможения, рулевого управления и ускорения.", "Использовать только пониженную передачу для улучшения сцепления.", "Регулярно притормаживать, чтобы проверить сцепление с дорожной поверхностью."], "correct": 1, "expl": "На ожеледиці зчеплення шин з дорогою мінімальне, тому будь-які різкі дії — гальмування, поворот керма чи прискорення — можуть миттєво спричинити занос.", "explSpecific": "Правильно — «Избегать резкого торможения, рулевого управления и ускорения». Регулярне підгальмовування «щоб не замерзли гальма» — вигадана й небезпечна порада; використання лише пониженої передачі саме по собі не вирішує проблему ожеледиці."}, {"num": 393, "text": "Какой наиболее безопасный способ движения по обледеневшей дороге?", "topic": "Швидкісний режим", "options": ["Ехать на меньшей скорости, чем обычно, плавно ускоряясь и притормаживая.", "Полностью положиться на ABS или другие передовые системы содействия управления транспортным средством.", "Ехать на пониженной передаче с максимальным ускорением.", "Ехать с нормальной скоростью, но периодически притормаживать, чтобы проверить сцепление."], "correct": 0, "expl": "На обледенілій дорозі найбезпечніший спосіб руху — їхати повільніше за звичайне, плавно прискорюючись і гальмуючи, без різких дій.", "explSpecific": "Правильно — «Ехать на меньшей скорости, чем обычно, плавно ускоряясь и притормаживая». Повне покладання на ABS замінює обережність технологією, що ризиковано; максимальне прискорення на пониженій передачі чи періодичне гальмування «для перевірки» зчеплення — небезпечні дії на льоду."}, {"num": 394, "text": "Каково воздействие обледенелых дорог на транспортное средство?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Сцепление шин улучшается при более низких температурах.", "Существует большая вероятность заноса транспортного средства.", "Давление в передних шинах увеличивается.", "Давление в задних шинах увеличивается."], "correct": 1, "expl": "Обледенілі дороги мають дуже низький коефіцієнт зчеплення, тому головний ефект — суттєво зростає ймовірність заносу автомобіля.", "explSpecific": "Правильно — «Существует большая вероятность заноса транспортного средства». Твердження про покращення зчеплення при низьких температурах чи зміну тиску в шинах через холод — фізично необґрунтовані вигадки."}, {"num": 395, "text": "Что следует делать водителю при движении по скользкой дороге?", "topic": "Погодні умови та видимість", "options": ["Сильно разогнаться, используя только нижние передачи.", "Постоянно притормаживать, чтобы улучшить сцепление шин.", "Двигаться медленнее, чем обычно, держась на близком расстоянии от автомобиля впереди.", "Плавно ускоряться и притормаживать."], "correct": 3, "expl": "На слизькій дорозі плавність усіх дій — прискорення й гальмування — головний спосіб уникнути втрати зчеплення й заносу.", "explSpecific": "Правильно — «Плавно ускоряться и притормаживать». Різкий розгін на нижчих передачах, постійне підгальмовування чи рух близько до автомобіля попереду підвищують, а не знижують ризик заносу."}, {"num": 396, "text": "Как водителю следует ехать по крутому склону или арочному мосту, когда дорога скользкая?", "topic": "Погодні умови та видимість", "options": ["Одновременно нажимая на педаль сцепления и тормоза.", "Нажимая на педаль сцепления.", "Ехать очень осторожно.", "На нейтральном положении передачи."], "correct": 2, "expl": "На слизькому крутому схилі чи арочному мосту головне правило — рухатися вкрай обережно, уникаючи будь-яких різких дій з педалями чи передачею.", "explSpecific": "Правильно — «Ехать очень осторожно». Одночасне натискання зчеплення й гальма, самé лише зчеплення чи нейтральна передача залишають автомобіль без контролю саме на слизькому схилі."}, {"num": 397, "text": "Помимо риска заноса, что следует знать водителю при движении по снегу?", "topic": "Дорожні знаки та розмітка", "options": ["Тормозная жидкость может замерзнуть, что приведет к отказу тормозов.", "Снег может накрыть дорожную разметку.", "Воздух в шинах может замерзнуть, что привести к их взрыву.", "Жидкость гидроусилителя руля может замерзнуть, что приведет к выходу из строя рулевого управления."], "correct": 1, "expl": "Крім ризику заносу, сніг має ще один прихований наслідок для водіння — він може повністю приховати дорожню розмітку під собою, роблячи межі смуг невидимими.", "explSpecific": "Правильно — «Снег может накрыть дорожную разметку». Варіанти про замерзання гальмівної рідини, повітря в шинах чи рідини гідропідсилювача — технічно малоймовірні чи вигадані сценарії, не типові для звичайного водіння по снігу."}, {"num": 398, "text": "Как должен действовать водитель при вождении в сильный дождь?", "topic": "Погодні умови та видимість", "options": ["Увеличить скорость, чтобы автомобиль скользил по стоячей воде.", "Немного вильнуть из стороны в сторону, чтобы улучшить сцепление шин.", "Ехать с обычной скоростью, как на сухой дороге.", "Он должен помнить, что транспортное средство может скользить или гидропланировать."], "correct": 3, "expl": "У сильний дощ водій повинен постійно пам'ятати про ризик ковзання чи аквапланування через шар води на дорозі.", "explSpecific": "Правильно — «Он должен помнить, что транспортное средство может скользить или гидропланировать». Збільшення швидкості, вихляння з боку в бік чи їзда зі звичайною швидкістю — небезпечні дії саме в сильний дощ."}, {"num": 399, "text": "Где может появиться наледь (черный лед) на дороге?", "topic": "Погодні умови та видимість", "options": ["Только на укрепленной части обочины.", "На защищенных или затененных участках.", "Только в застроенных районах.", "В теплую погоду на прибрежной дороге."], "correct": 1, "expl": "Ожеледиця найчастіше утворюється на захищених від сонця чи затінених ділянках дороги (під деревами, мостами, в улоговинах), де температура довше залишається біля нуля.", "explSpecific": "Правильно — «На защищенных или затененных участках». Прив'язка виключно до узбіччя, забудованих районів чи теплої погоди на прибережній дорозі не відповідає реальним умовам утворення ожеледиці."}, {"num": 400, "text": "Что должен делать водитель если видит грязь на дороге?", "topic": "Погодні умови та видимість", "options": ["Немедленно затормозить и включить аварийные огни.", "Снизить скорость и быть готовым к появлению сельскохозяйственных или дорожно-ремонтных транспортных средств.", "Постепенно увеличить скорость, чтобы грязь на дороге не прилипала к шинам.", "Переключиться на пониженную передачу и прокачать тормоза, чтобы увидеть, насколько поверхность скользкая."], "correct": 1, "expl": "Бруд на дорозі часто вказує на присутність поруч сільськогосподарської чи ремонтної техніки, тому водій має знизити швидкість і бути готовим до появи такого транспорту.", "explSpecific": "Правильно — «Снизить скорость и быть готовым к появлению сельскохозяйственных или дорожно-ремонтных транспортных средств». Різке гальмування з аварійними вогнями чи перевірка слизькості гальмуванням — недоречні реакції на забруднену дорогу."}, {"num": 401, "text": "В чем опасность езды на высоких скоростях по мокрым дорогам?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Опасность гидропланирования или скольжения по поверхности дороги.", "Опасность автоматического увеличения давления в шинах.", "Опасность отсутствует если давление в шинах увеличено с учетом погодных условий.", "Опасность отсутствует при условии, что давление в шинах уменьшено с учетом погодных условий."], "correct": 0, "expl": "На високій швидкості по мокрій дорозі шини можуть втратити контакт з покриттям через шар води (аквапланування), що призводить до втрати керованості.", "explSpecific": "Правильно — «Опасность гидропланирования или скольжения». Варіанти про автоматичну зміну тиску в шинах — вигадані; «небезпеки немає» за певного тиску прямо суперечить реальній фізиці аквапланування."}, {"num": 402, "text": "О чем должен знать водитель при пересечении дорожной разметки, такой как линии или стрелки?", "topic": "Дорожні знаки та розмітка", "options": ["Сцепление шин уменьшается.", "Рулевое управление улучшается.", "Сцепление шин улучшается.", "Это не влияет на сцепление шин."], "correct": 0, "expl": "Дорожня розмітка (фарба) сама по собі має нижчий коефіцієнт зчеплення, ніж асфальт, тому під час перетину ліній чи стрілок зчеплення шин з дорогою тимчасово погіршується.", "explSpecific": "Правильно — «Сцепление шин уменьшается». «Кермування покращується» і «зчеплення покращується» прямо суперечать фізичним властивостям фарбованої поверхні; «не впливає» ігнорує реальний, хоч і невеликий, ефект розмітки на зчеплення."}, {"num": 403, "text": "Что делать водителю после проезда через затопленный участок дороги?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Слегка нажимать педаль тормоза на малой скорости и проехать небольшое расстояние, чтобы высушить тормоза.", "Нажать на тормоза, чтобы проверить их исправность.", "Постепенно включить ручной тормоз, чтобы высушить только задние тормоза.", "Увеличить скорость транспортного средства, чтобы просушить тормоза."], "correct": 0, "expl": "Після проїзду через воду гальмівні колодки й диски можуть намокнути і тимчасово втратити ефективність, тому їх варто просушити легким натисканням на гальмо на невеликій швидкості.", "explSpecific": "Правильно — «Слегка нажимать педаль тормоза на малой скорости... чтобы высушить тормоза». Різке натискання на гальмо для «перевірки» чи збільшення швидкості небезпечні одразу після проїзду через воду; ручний гальмівний важіль сушить лише задні гальма."}, {"num": 404, "text": "Что должен делать водитель, если на участке дороги впереди есть неглубокая зона затопления?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Увеличить скорость и ехать на более высокой передаче.", "Снизить скорость и ехать на более высокой передаче.", "Ехать на низкой передаче как можно медленнее, поддерживая высокие обороты двигателя.", "Используйте высокую передачу и сохранять ту же скорость, поддерживая низкие обороты двигателя."], "correct": 2, "expl": "Проїжджаючи неглибоку зону затоплення, важливо рухатись повільно на низькій передачі з високими обертами двигуна, щоб вода не потрапила у вихлопну трубу і не заглушила двигун.", "explSpecific": "Правильно — «Ехать на низкой передаче как можно медленнее, поддерживая высокие обороты двигателя». Збільшення швидкості створює хвилю, що може залити двигун; висока передача з низькими обертами підвищує ризик заглухнути посеред води."}, {"num": 405, "text": "Кому водитель должен сообщать об агрессивном вождении?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Управление транспортной инфраструктуры Ирландии", "Управление по безопасности дорожного движения.", "Службу безопасности и здравоохранения.", "Службу дорожного патруля или Гарду."], "correct": 3, "expl": "Про агресивне водіння на дорозі слід повідомляти саме поліцію (Гарду) чи дорожній патруль — органи, уповноважені реагувати на порушення правил дорожнього руху.", "explSpecific": "Правильно — «Службу дорожного патруля или Гарду». Управління транспортної інфраструктури чи безпеки дорожнього руху займаються плануванням і стандартами, а не реагуванням на конкретні інциденти."}, {"num": 406, "text": "Что должен делать водитель, приближаясь к знакам в местах проведения дорожных работ?", "topic": "Погодні умови та видимість", "options": ["Увеличить скорость и переместиться ближе к центру дороги.", "Снизить скорость и приготовиться к остановке, чтобы пропустить дорожно-ремонтные транспортные средства или дождаться сигнала регулировщика.", "Включить более высокую передачу, чтобы не застрять в смоле.", "Увеличить скорость, пока регулировщик не подаст сигнал о необходимости ее уменьшения."], "correct": 1, "expl": "Наближаючись до знаків дорожніх робіт, водій повинен знизити швидкість і бути готовим зупинитися, пропускаючи ремонтну техніку чи очікуючи сигнал регулювальника.", "explSpecific": "Правильно — «Снизить скорость и приготовиться к остановке...». Збільшення швидкості чи наближення до центру дороги суперечать обережності в зоні робіт; перемикання передачі «щоб не застрягти в смолі» — вигадана причина."}, {"num": 407, "text": "О чем должен помнить водитель, проезжая участок дороги, на котором ведутся дорожные работы?", "topic": "Обгін та зміна смуги руху", "options": ["У водителя есть преимущественное право проезда перед дорожно- ремонтными транспортными средствами.", "Более узкие полосы, чем обычно, и ограничение укрепленной части обочины.", "Именно дорожники всегда в курсе движения транспорта.", "Этот участок будет хорошо очищен для водителя, чтобы не было задержек движения."], "correct": 1, "expl": "На ділянці дорожніх робіт водій повинен пам'ятати про типово вужчі смуги руху та обмежений доступ до укріпленої частини узбіччя.", "explSpecific": "Правильно — «Более узкие полосы, чем обычно, и ограничение укрепленной части обочины». Твердження про пріоритет водія над ремонтною технікою — необґрунтоване припущення; обіцянка розчищеної без затримок ділянки нереалістична."}, {"num": 408, "text": "При желании повернуть направо в конце улицы с односторонним движением, где водитель должен расположить свое транспортное средство?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Как можно ближе к правой стороне дороги.", "Как можно ближе к левой стороне дороги.", "Как можно дальше от правой стороны дороги.", "Как можно ближе к центру дороги."], "correct": 0, "expl": "На односторонній вулиці для повороту праворуч в кінці водій має розташуватися якомога ближче до правого краю дороги завчасно, щоб виконати чіткий поворот.", "explSpecific": "Правильно — «Как можно ближе к правой стороне дороги». Розташування ліворуч чи по центру не відповідає правилу позиціонування «займай смугу за напрямком повороту» для односторонньої вулиці."}, {"num": 409, "text": "Что должен делать водитель, когда водитель хочет повернуть налево к своему дому, и слева находится полоса движения автобусов?", "topic": "Обгін та зміна смуги руху", "options": ["Водитель должен пропустить только автобусы.", "Уступить дорогу велосипедистам и такси, которые могут использовать полосу движения автобусов.", "Уступить дорогу велосипедистам, такси и автобусам, которые могут использовать полосу движения автобусов.", "Водитель никогда не должен поворачивать налево, чтобы проехать через полосу движения автобусов."], "correct": 2, "expl": "Повертаючи ліворуч через смугу для автобусів, водій повинен поступитися дорогою всім категоріям транспорту, яким дозволено рухатися цією смугою.", "explSpecific": "Правильно — «Уступить дорогу велосипедистам, такси и автобусам». Обмеження лише автобусами звужує реальний перелік дозволених користувачів смуги; заборона повороту ліворуч через таку смугу взагалі не відповідає дійсності."}, {"num": 410, "text": "Какой транспорт может использовать встречную полосу движения автобусов?", "topic": "Обгін та зміна смуги руху", "options": ["Только автобусы и механизированные инвалидные коляски", "Автобусы, такси и мотоциклы.", "Автобусы, работающие по расписанию.", "Автобусы, такси и велосипеды."], "correct": 2, "expl": "Зустрічну смугу руху автобусів можуть використовувати лише автобуси, що рухаються за розкладом регулярного маршруту, а не будь-який громадський чи спеціальний транспорт.", "explSpecific": "Правильно — «Автобусы, работающие по расписанию». Включення таксі, мотоциклів, велосипедів чи інвалідних візків у перелік не відповідає точному правилу, яке стосується лише регулярних маршрутів."}, {"num": 411, "text": "Какой транспорт может использовать попутную полосу движения автобусов в течение времени, указанного на информационных знаках в начале полосы?", "topic": "Обгін та зміна смуги руху", "options": ["Весь транспорт.", "Транспортные средства с несколькими пассажирами.", "Автобусы, такси и велосипеды.", "Только автобусы."], "correct": 2, "expl": "Попутну смугу для автобусів у визначені години можуть використовувати ширше коло учасників руху — автобуси, таксі й велосипедисти, а не лише автобуси.", "explSpecific": "Правильно — «Автобусы, такси и велосипеды». «Весь транспорт» надто широко розширює перелік; «транспортні засоби з кількома пасажирами» — вигаданий критерій; «тільки автобуси» звужує реальний перелік."}, {"num": 412, "text": "Какой штраф предусмотрен за вождение в нетрезвом состоянии для водителя при концентрации алкоголя в крови (ВАС) от 80 мг до 100 мг на 100 миллилитров крови?", "topic": "Штрафні бали, права та документи", "options": ["Штраф в размере 200 евро и лишение водительских прав на 6 месяцев.", "Штраф в размере 400 евро и лишение водительских прав на 6 месяцев.", "Штраф в размере 200 евро и лишение водительских прав на 3 месяцев.", "Штраф в размере 400 евро и лишение водительских прав на 3 месяцев."], "correct": 1, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Тут усі варіанти відрізняються переважно конкретним числовим значенням — це питання на запам'ятовування точного нормативу, а не на логіку. Правильне значення саме таке, яке вказано у правильній відповіді; інші цифри в цьому питанні — невірні нормативи, які варто не переплутати."}, {"num": 413, "text": "Какой штраф применяется для водителя, который отказывается дышать в трубку, сдавать образцы крови или мочи в качестве доказательства повторного преступления против An Gárda Siochána?", "topic": "Штрафні бали, права та документи", "options": ["Автоматическая дисквалификация на 12 месяцев.", "Автоматическая дисквалификация на 3 месяца.", "Автоматическая дисквалификация на 4 года.", "Автоматическая дисквалификация на 6 лет."], "correct": 3, "expl": "Ці питання перевіряють базовий принцип безпечного водіння: передбачати дії інших учасників руху й лишати запас часу та простору для реакції. Правильна відповідь зазвичай та, що зменшує ризик або невизначеність (більша дистанція, менша швидкість, більша увага), а не та, що просто найшвидша чи найзручніша для водія. Ірландські правила приділяють велику увагу відповідальності водія за стан транспортного засобу та за передбачувану, а не реактивну манеру керування.", "explSpecific": "Правильна відповідь тут — «Автоматическая дисквалификация на 6 лет». Інші варіанти в цьому питанні («Автоматическая дисквалификация на 12 месяцев», «Автоматическая дисквалификация на 3 месяца» та «Автоматическая дисквалификация на 4 года») не відповідають цій вимозі й тому неправильні."}, {"num": 414, "text": "На какой полосе движения должен находиться водитель на двухполосной дороге в нормальных условиях движения?", "topic": "Обгін та зміна смуги руху", "options": ["На любой полосе.", "На правой полосе движения, за исключением случаев, когда вы управляете дорожно-ремонтным транспортным средством или грузовиком.", "На левой полосе, если водитель не хочет совершить обгон или повернуть направо.", "На правой полосе."], "correct": 2, "expl": "На двосмуговій дорозі в звичайних умовах водій повинен рухатися лівою смугою, переходячи на праву лише для обгону чи повороту праворуч.", "explSpecific": "Правильно — «На левой полосе, если водитель не хочет совершить обгон или повернуть направо». «Будь-яка смуга» і «права смуга завжди» суперечать базовому правилу тримання лівого боку."}, {"num": 415, "text": "Может ли Гарда по утрам на дорогах проводить тесты на содержание наркотиков и алкоголя в крови водителей?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Они могут провести только тест на содержание алкоголя в крови.", "Они могут провести только тест на содержание наркотиков в крови.", "Да, они могут провести тесты в любое время.", "Нет, они не могут проводить тесты до полудня."], "correct": 2, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Да, они могут провести тесты в любое время». Інші варіанти в цьому питанні («Они могут провести только тест на содержание алкоголя в крови», «Они могут провести только тест на содержание наркотиков в крови» та «Нет, они не могут проводить тесты до полудня») не відповідають цій вимозі й тому неправильні."}, {"num": 416, "text": "Что может запросить Гарда, наряду с тестом на нарушение, если они подозревают, что водитель за рулем находится под воздействием наркотиков?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Страховой сертификат.", "Образец слюны.", "Водительское удостоверение.", "Образец выдыхаемого воздуха."], "correct": 1, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Образец слюны». Інші варіанти в цьому питанні («Страховой сертификат», «Водительское удостоверение» та «Образец выдыхаемого воздуха») не відповідають цій вимозі й тому неправильні."}, {"num": 417, "text": "Из чего состоит дорога типа 2+1?", "topic": "Обгін та зміна смуги руху", "options": ["Две не автомагистральные полосы в одном направлении и одна не автомагистральная полоса в противоположном направлении.", "Две автомагистральные полосы в одном направлении и одна не автомагистральная полоса в противоположном направлении.", "Две не автомагистральные полосы и одна автомагистральная полоса в двух направлениях.", "Две автомагистральные полосы и одна не автомагистральная полоса в двух направлениях."], "correct": 0, "expl": "Дорога типу «2+1» — особлива схема, де почергово то один, то інший напрямок отримує дві смуги для безпечного обгону, а протилежний — одну, і смуги при цьому НЕ мають статусу автомагістралі.", "explSpecific": "Правильно — «Две не автомагистральные полосы в одном направлении и одна не автомагистральная полоса в противоположном направлении». Варіанти зі статусом «автомагістральна смуга» неточні для цього типу дороги."}, {"num": 418, "text": "Каков максимальный штраф за вождение в нетрезвом виде?", "topic": "Штрафні бали, права та документи", "options": ["Штраф в размере 3 000 евро и лишение свободы на 12 месяцев.", "Штраф в размере 3 000 евро и лишение водительских прав на 12 месяцев.", "Штраф в размере 5 000 евро и лишение свободы на 6 месяцев.", "Штраф в размере 5 000 евро и лишение водительских прав на 6 месяцев."], "correct": 2, "expl": "Ці питання перевіряють знання адміністративних наслідків порушень: штрафні бали, штрафи, дискваліфікація водія-учня чи обов'язкове страхування чи техогляд. Тут немає «логіки» в сенсі фізики дороги — це конкретні цифри й строки, встановлені законодавством, тому такі питання варто саме запам'ятовувати, а не виводити логічно.", "explSpecific": "Тут усі варіанти відрізняються переважно конкретним числовим значенням — це питання на запам'ятовування точного нормативу, а не на логіку. Правильне значення саме таке, яке вказано у правильній відповіді; інші цифри в цьому питанні — невірні нормативи, які варто не переплутати."}, {"num": 419, "text": "Где водителю разрешается совершить обгон на дороге типа 2 плюс 1?", "topic": "Обгін та зміна смуги руху", "options": ["На двухполосном участке.", "На однополосном участке, если нет встречного движения.", "На однополосном участке.", "На однополосном или на двухполосном участке."], "correct": 0, "expl": "На дорозі типу «2+1» обгін дозволений саме на тій ділянці, де ваш напрямок отримує дві смуги.", "explSpecific": "Правильно — «На двухполосном участке». Обгін на односмуговому відрізку небезпечний і не є призначенням цієї схеми — саме для обгону виділяється по черзі двосмуговий відрізок."}, {"num": 420, "text": "Что должен делать водитель, когда он едет по автомагистрали или по двухполосной дороге?", "topic": "Автомагістраль і тунелі", "options": ["Быть внимательным к другим водителям, которые могут внезапно сменить полосу движения или снизить скорость.", "Ехать со скоростью не менее 80 км/ч", "Ехать со скоростью не более 60 км/ч", "Ехать со скоростью не менее 100 км/ч"], "correct": 0, "expl": "На автомагістралі і в тунелі головні ризики — це висока швидкість потоку і обмежені можливості для зупинки чи розвороту. Тому правила вимагають додаткової підготовки заздалегідь (перевірка пального, справності авто), підтримання дистанції пропорційної швидкості, і чітких дій у разі затору чи поломки — увімкнути аварійну сигналізацію, за можливості з'їхати на узбіччя чи в аварійну нішу, і не залишатись у смузі руху.", "explSpecific": "Правильна відповідь тут — «Быть внимательным к другим водителям, которые могут внезапно сменить полосу движения или снизить скорость». Інші варіанти в цьому питанні («Ехать со скоростью не менее 80 км/ч», «Ехать со скоростью не более 60 км/ч» та «Ехать со скоростью не менее 100 км/ч») не відповідають цій вимозі й тому неправильні."}, {"num": 421, "text": "Что делать водителю при движении по автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Двигаться по боковой (правосторонней) полосе, если он не собирается совершать обгон.", "Двигаться по боковой (левосторонней) полосе, если он не собирается совершать обгон.", "Обязательно обогнать впереди идущее транспортное средство со скоростью не менее 80 км/ч.", "Обязательно обогнать впереди идущее транспортное средство со скоростью не менее 100 км/ч."], "correct": 1, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Двигаться по боковой (левосторонней) полосе, если он не собирается совершать обгон». Інші варіанти в цьому питанні («Двигаться по боковой (правосторонней) полосе, если он не собирается совершать обгон», «Обязательно обогнать впереди идущее транспортное средство со скоростью не менее 80 км/ч» та «Обязательно обогнать впереди идущее транспортное средство со скоростью не менее 100 км/ч») не відповідають цій вимозі й тому неправильні."}, {"num": 422, "text": "Какое из следующих утверждений верно в отношении давления в шинах и движения по автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Водитель должен увеличить давление в задних шинах, чтобы справиться с устойчивой высокой скоростью.", "Водитель должен увеличить давление в передних шинах, чтобы справиться с устойчивой высокой скоростью.", "Водитель должен уменьшить давление в шинах, поскольку высокие скорости вызовут их нагрев.", "Водитель должен убедиться, что давление в шинах правильное, в соответствии с рекомендациями производителя."], "correct": 3, "expl": "На автомагістралі і в тунелі головні ризики — це висока швидкість потоку і обмежені можливості для зупинки чи розвороту. Тому правила вимагають додаткової підготовки заздалегідь (перевірка пального, справності авто), підтримання дистанції пропорційної швидкості, і чітких дій у разі затору чи поломки — увімкнути аварійну сигналізацію, за можливості з'їхати на узбіччя чи в аварійну нішу, і не залишатись у смузі руху.", "explSpecific": "Правильна відповідь тут — «Водитель должен убедиться, что давление в шинах правильное, в соответствии с рекомендациями производителя». Інші варіанти в цьому питанні («Водитель должен увеличить давление в задних шинах, чтобы справиться с устойчивой высокой скоростью», «Водитель должен увеличить давление в передних шинах, чтобы справиться с устойчивой высокой скоростью» та «Водитель должен уменьшить давление в шинах, поскольку высокие скорости вызовут их нагрев») не відповідають цій вимозі й тому неправильні."}, {"num": 423, "text": "Что должен делать водитель при въезде на автомагистраль с подъездной дороги?", "topic": "Автомагістраль і тунелі", "options": ["Попытаться скорректировать скорость транспортного средства в соответствии со скоростью транспорта, уже едущего по автомагистрали, и въехать на нее при появлении подходящего зазора.", "Въехать прямо на автомагистраль, поскольку водитель на полосе ускорения имеет преимущественное право проезда.", "Двигаться вдоль укрепленной части обочины до тех пор, пока на проезжей части автомагистрали не появится подходящий зазор, позволяющий водителю въехать в него.", "Всегда останавливаться в конце подъездной дороги и уступать дорогу транспорту, движущемуся по автомагистрали."], "correct": 0, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Попытаться скорректировать скорость транспортного средства в соответствии со скоростью транспорта, уже едущего по автомагистрали, и въехать на нее при появлении подходящего зазора». Інші варіанти в цьому питанні («Въехать прямо на автомагистраль, поскольку водитель на полосе ускорения имеет преимущественное право проезда», «Двигаться вдоль укрепленной части обочины до тех пор, пока на проезжей части автомагистрали не появится подходящий зазор, позволяющий водителю въехать в него» та «Всегда останавливаться в конце подъездной дороги и уступать дорогу транспорту, движущемуся по автомагистрали») не відповідають цій вимозі й тому неправильні."}, {"num": 424, "text": "Что должен делать водитель при въезде на автомагистраль с подъездной дороги?", "topic": "Погодні умови та видимість", "options": ["Воспользоваться габаритами транспортного средства, чтобы утвердить свое положение на автомагистрали.", "Остановиться на подъездной дороге и ждать, пока не появится подходящий зазор для въезда.", "Скорректировать скорость таким образом, чтобы она соответствовала скорости движения по автомагистрали, и въехать, когда появится подходящий зазор.", "Ехать по укрепленной части обочины и дождаться, пока не появится подходящий зазор для въезда."], "correct": 2, "expl": "В'їжджаючи на автомагістраль з під'їзної дороги, водій повинен розігнатися до швидкості потоку автомагістралі і влитися в рух, коли з'явиться безпечний проміжок, а не зупинятися чи повзти по узбіччю.", "explSpecific": "Правильно — «Скорректировать скорость... и въехать, когда появится подходящий зазор». Зупинка на під'їзній смузі чи рух по укріпленому узбіччю — небезпечні альтернативи."}, {"num": 425, "text": "Что нужно делать водителю на автомагистрали, если он пропустил свой съезд?", "topic": "Автомагістраль і тунелі", "options": ["Покинуть автомагистраль на следующем съезде и переместиться на другую сторону, через пролет (или подземный переход).", "Подождать на укрепленной части обочины, пока в движении не появится подходящий зазор с обоих направлений, а затем переехать на противоположную сторону автомагистрали.", "Остановиться на укрепленной части обочины, включить аварийные огни и вернуться к желаемому съезду.", "Переместиться на противоположную сторону автомагистрали, когда в полосе встречного движения появится подходящий зазор."], "correct": 0, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Покинуть автомагистраль на следующем съезде и переместиться на другую сторону, через пролет (или подземный переход)». Інші варіанти в цьому питанні («Подождать на укрепленной части обочины, пока в движении не появится подходящий зазор с обоих направлений, а затем переехать на противоположную сторону автомагистрали», «Остановиться на укрепленной части обочины, включить аварийные огни и вернуться к желаемому съезду» та «Переместиться на противоположную сторону автомагистрали, когда в полосе встречного движения появится подходящий зазор») не відповідають цій вимозі й тому неправильні."}, {"num": 426, "text": "Что делать водителю, если он по ошибке проезжает мимо намеченного съезда?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Остановиться на укрепленной части обочины и вернуться обратно к съезду.", "Продолжать движение и выехать на следующем съезде.", "Использовать экстренный телефон, чтобы спросить совета.", "Осторожно завершить разворот."], "correct": 1, "expl": "Якщо водій проїхав повз потрібний з'їзд з автомагістралі, єдина безпечна дія — продовжити рух до наступного з'їзду, а не намагатися повернутися заднім ходом чи розвернутися.", "explSpecific": "Правильно — «Продолжать движение и выехать на следующем съезде». Зупинка на узбіччі, щоб повернутися назад, і розворот на автомагістралі — вкрай небезпечні й заборонені маневри."}, {"num": 427, "text": "Разрешено ли водителю подбирать и высаживать пассажиров на автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Водителю запрещено подбирать и высаживать пассажиров на автомагистрали.", "Это разрешается при условии, что водитель остановится на укрепленной части обочины.", "Разрешено только в дневное время.", "Разрешено на расстоянии 200 метров от подъездной дороги."], "correct": 0, "expl": "На автомагістралі і в тунелі головні ризики — це висока швидкість потоку і обмежені можливості для зупинки чи розвороту. Тому правила вимагають додаткової підготовки заздалегідь (перевірка пального, справності авто), підтримання дистанції пропорційної швидкості, і чітких дій у разі затору чи поломки — увімкнути аварійну сигналізацію, за можливості з'їхати на узбіччя чи в аварійну нішу, і не залишатись у смузі руху.", "explSpecific": "Правильна відповідь тут — «Водителю запрещено подбирать и высаживать пассажиров на автомагистрали». Інші варіанти в цьому питанні («Это разрешается при условии, что водитель остановится на укрепленной части обочины», «Разрешено только в дневное время» та «Разрешено на расстоянии 200 метров от подъездной дороги») не відповідають цій вимозі й тому неправильні."}, {"num": 428, "text": "Что должен делать водитель, когда выезжает на подъездную дорогу с автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Соблюдать скоростное ограничение на дороге, на которую он въезжает.", "Всегда постепенно снижать скорость на несколько километров.", "Никогда не нужно регулировать скорость на скользкой дороге.", "Сильно тормозить при въезде на подъездную дорогу, чтобы замедлиться."], "correct": 0, "expl": "У складних погодних умовах (дощ, туман, ожеледь, темрява) гальмівний шлях зростає, а видимість — падає, тому логіка завжди одна: знизити швидкість і збільшити дистанцію до попереднього автомобіля пропорційно погіршенню умов. У тумані використовують ближнє світло (не дальнє — воно відбивається від крапель вологи і засліплює самого водія), а протитуманні фари вмикають лише за дійсно поганої видимості. Це пояснює, чому відповіді на кшталт «зменшити швидкість», «збільшити дистанцію» чи «увімкнути ближнє світло» майже завжди правильні в цій темі.", "explSpecific": "Правильна відповідь тут — «Соблюдать скоростное ограничение на дороге, на которую он въезжает». Інші варіанти в цьому питанні («Всегда постепенно снижать скорость на несколько километров», «Никогда не нужно регулировать скорость на скользкой дороге» та «Сильно тормозить при въезде на подъездную дорогу, чтобы замедлиться») не відповідають цій вимозі й тому неправильні."}, {"num": 429, "text": "Различаются ли предельные показатели в случае алкогольного или наркотического опьянения в случае обнаружения в утренние часы?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Да, они выше вечером.", "Да, они ниже вечером.", "Нет в случае проверки после 10.00.", "Нет, они одинаковы в любое время."], "correct": 3, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Нет, они одинаковы в любое время». Інші варіанти в цьому питанні («Да, они выше вечером», «Да, они ниже вечером» та «Нет в случае проверки после 10.00») не відповідають цій вимозі й тому неправильні."}, {"num": 430, "text": "Что делать водителю после выезда с автострады и движения в направлении развязки в конце полосы замедления?", "topic": "Автомагістраль і тунелі", "options": ["Водитель должен всегда останавливаться в конце скользкой дороги.", "Быть внимательным при встречном и перекрестном движении в конце подъездной дороги.", "Водитель должен продолжить движение на перекрестке, так как транспорт на подъездной дороге имеет право проезда.", "Поддерживать скорость, предусмотренную для автомагистрали до конца подъездной дороги."], "correct": 1, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Быть внимательным при встречном и перекрестном движении в конце подъездной дороги». Інші варіанти в цьому питанні («Водитель должен всегда останавливаться в конце скользкой дороги», «Водитель должен продолжить движение на перекрестке, так как транспорт на подъездной дороге имеет право проезда» та «Поддерживать скорость, предусмотренную для автомагистрали до конца подъездной дороги») не відповідають цій вимозі й тому неправильні."}, {"num": 431, "text": "На 2-полосной автомагистрали, что должен сделать водитель при желании безопасно обогнать другое транспортное средство?", "topic": "Автомагістраль і тунелі", "options": ["Он должен посмотреть в зеркала, включить поворот и обогнать по правой полосе, когда это будет безопасно.", "Он должен посмотреть в зеркала, включить поворот и обогнать только по левой полосе.", "Он должен посмотреть в зеркала, включить поворот и обогнать по любой полосе, когда это будет безопасно.", "Убедиться, нет ли позади него другого транспорта и совершить обгон по любой полосе."], "correct": 0, "expl": "Обгін — один із найризикованіших маневрів, тому правило завжди на боці обережності: обганяти можна лише коли є чіткий огляд дороги попереду, достатньо місця для повернення в свою смугу і жоден інший учасник руху цьому не заважає. Заборонено обганяти перед перехрестям, на підйомі, повороті, пішохідному переході чи там, де розмітка суцільна. При обгоні вразливих учасників руху (велосипедистів, пішоходів) потрібна більша бічна дистанція, ніж при обгоні авто — це і пояснює, чому в таких питаннях правильна відповідь часто підкреслює саме дистанцію чи очікування безпечного моменту.", "explSpecific": "Правильна відповідь тут — «Он должен посмотреть в зеркала, включить поворот и обогнать по правой полосе, когда это будет безопасно». Інші варіанти в цьому питанні («Он должен посмотреть в зеркала, включить поворот и обогнать только по левой полосе», «Он должен посмотреть в зеркала, включить поворот и обогнать по любой полосе, когда это будет безопасно» та «Убедиться, нет ли позади него другого транспорта и совершить обгон по любой полосе») не відповідають цій вимозі й тому неправильні."}, {"num": 432, "text": "Для чего может использоваться укрепленная часть обочины?", "topic": "Паркування та зупинка", "options": ["Остановка в аварийной ситуации.", "Выезд с автомагистрали.", "Остановка для использования мобильного телефона.", "Выезд на автомагистраль."], "correct": 0, "expl": "Укріплена частина узбіччя автомагістралі призначена виключно для зупинки в аварійній ситуації — поломки чи іншої надзвичайної події.", "explSpecific": "Правильно — «Остановка в аварийной ситуации». Використання узбіччя як звичайного виїзду чи в'їзду на автомагістраль або для розмови по телефону — заборонені й небезпечні застосування."}, {"num": 433, "text": "Водитель желает ехать прямо на равнозначном перекрестке. Если они столкнется с другим транспортом, какое общее правило применяется?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Уступить дорогу транспорту, приближающемуся только слева.", "Уступить дорогу транспорту, приближающемуся сначала слева, а затем справа.", "Продолжать движение как обычно, поскольку он всегда имеет право проезда.", "Транспорт, движущийся со стороны водителя, имеет преимущественное право проезда."], "correct": 3, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Транспорт, движущийся со стороны водителя, имеет преимущественное право проезда». Інші варіанти в цьому питанні («Уступить дорогу транспорту, приближающемуся только слева», «Уступить дорогу транспорту, приближающемуся сначала слева, а затем справа» та «Продолжать движение как обычно, поскольку он всегда имеет право проезда») не відповідають цій вимозі й тому неправильні."}, {"num": 434, "text": "Как езда на высокой скорости влияет на устойчивость автомобиля на дороге?", "topic": "Швидкісний режим", "options": ["Расположение колес обеспечивает полный контакт шин с дорогой.", "Подвеска компенсирует любые неровности дорожного покрытия.", "Устойчивость автомобиля к дороге снижается.", "Повышается курсовая устойчивость автомобиля."], "correct": 2, "expl": "На високій швидкості стійкість автомобіля до дороги знижується, оскільки шини мають менше часу контакту з покриттям на кожній нерівності.", "explSpecific": "Правильно — «Устойчивость автомобиля к дороге снижается». Твердження про повний контакт шин через розташування коліс чи компенсацію нерівностей підвіскою применшують реальний фізичний ефект швидкості; «підвищується курсова стійкість» — прямо протилежний висновок."}, {"num": 435, "text": "Что должен делать водитель, когда едет вниз по снегу или льду?", "topic": "Погодні умови та видимість", "options": ["Избегать использования тормоза и использовать высокую передачу.", "Выбрать подходящую передачу и осторожно затормозить, чтобы контролировать скорость.", "Держаться ближе к левому краю и резко тормозить, чтобы снизить скорость.", "Использовать более высокую передачу, чем обычно, чтобы избежать пробуксовки колес."], "correct": 1, "expl": "Спускаючись по снігу чи льоду, водій повинен обрати відповідну (понижену) передачу і обережно гальмувати, щоб контролювати швидкість без заносу.", "explSpecific": "Правильно — «Выбрать подходящую передачу и осторожно затормозить, чтобы контролировать скорость». Уникнення гальма з високою передачею чи різке гальмування ближче до краю — небезпечні крайнощі."}, {"num": 436, "text": "В чем основное отличие езды по автомагистрали от движения по другим типам дорог?", "topic": "Автомагістраль і тунелі", "options": ["Движение по автомагистрали обычно происходит с меньшей скоростью, чем по двухполосной дороге.", "Владельцы водительских удостоверений обучаемых вождению должны сопровождаться владельцем полноценного водительского удостоверения.", "Транспорту на автомагистрали, как правило разрешается движение на более высокой скорости.", "Для движения со скоростью 120 км/ч необходимо использовать только внешнюю полосу автомагистрали."], "correct": 2, "expl": "На автомагістралі і в тунелі головні ризики — це висока швидкість потоку і обмежені можливості для зупинки чи розвороту. Тому правила вимагають додаткової підготовки заздалегідь (перевірка пального, справності авто), підтримання дистанції пропорційної швидкості, і чітких дій у разі затору чи поломки — увімкнути аварійну сигналізацію, за можливості з'їхати на узбіччя чи в аварійну нішу, і не залишатись у смузі руху.", "explSpecific": "Правильна відповідь тут — «Транспорту на автомагистрали, как правило разрешается движение на более высокой скорости». Інші варіанти в цьому питанні («Движение по автомагистрали обычно происходит с меньшей скоростью, чем по двухполосной дороге», «Владельцы водительских удостоверений обучаемых вождению должны сопровождаться владельцем полноценного водительского удостоверения» та «Для движения со скоростью 120 км/ч необходимо использовать только внешнюю полосу автомагистрали») не відповідають цій вимозі й тому неправильні."}, {"num": 437, "text": "Что нужно сделать водителю при парковке автомобиля в гору на улице с двусторонним движением?", "topic": "Паркування та зупинка", "options": ["Повернуть рулевое колесо вправо.", "Повернуть рулевое колесо влево.", "Вывернуть рулевое колесо прямо.", "Ничего не нужно делать."], "correct": 0, "expl": "Паркуючись у гору на вулиці з двостороннім рухом, водій повинен повернути передні колеса праворуч, щоб у разі скочування автомобіль укотився в бордюр, а не на проїзну частину.", "explSpecific": "Правильно — «Повернуть рулевое колесо вправо». Поворот ліворуч чи пряме положення коліс не захищають від скочування на смугу зустрічного руху; бездіяльність ігнорує базову вимогу безпечної стоянки на схилі."}, {"num": 438, "text": "Что должен делать водитель во время движения по основной дороге, которая не разделена центральной разделительной линией?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Вообразить, что существует центральная линия и двигаться по левой стороне.", "Вообразить, что существует центральная линия и двигаться по правой стороне.", "Двигаться строго по центру дороги.", "Двигаться в зависимости от ситуации, сначала по правой затем - по левой стороне."], "correct": 0, "expl": "На дорозі без розмітки центральної лінії водій все одно зобов'язаний подумки уявити її наявність і рухатися лівою стороною, як того вимагає лівосторонній рух в Ірландії.", "explSpecific": "Правильно — «Вообразить, что существует центральная линия и двигаться по левой стороне». Рух по правій стороні чи по центру дороги суперечить базовому правилу лівостороннього руху."}, {"num": 439, "text": "Что должен делать водитель, приближаясь к крутому изгибу справа на узкой дороге?", "topic": "Швидкісний режим", "options": ["Уменьшить скорость, держаться правее и следить за встречным движением.", "Уменьшить скорость, держаться левее и смотреть в зеркало заднего вида.", "Уменьшить скорость, держаться левее и следить за встречным движением.", "Уменьшить скорость, держаться правее и смотреть в зеркало заднего вида."], "correct": 2, "expl": "Наближаючись до крутого вигину дороги праворуч на вузькій дорозі, водій повинен знизити швидкість, триматися лівого боку і уважно стежити за зустрічним транспортом, який може виникнути з-за повороту.", "explSpecific": "Правильно — «Уменьшить скорость, держаться левее и следить за встречным движением». Триматися правого боку на вузькому вигині підвищує ризик зіткнення із зустрічним транспортом; погляд у дзеркало заднього виду не відповідає головній небезпеці попереду."}, {"num": 440, "text": "При приближении к кольцевой развязке, кому водитель должен уступить дорогу?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["На кольцевой развязке водитель должен уступать дорогу только большегрузным транспортным средствам.", "Водитель, приближающийся к кольцевой развязке, всегда имеет преимущественное право проезда.", "Водитель должен уступить дорогу транспорту, движущемуся справа или уже находящемуся на кольцевой развязке.", "На кольцевой развязке водитель должен уступать дорогу только пешеходам и велосипедистам."], "correct": 2, "expl": "На перехресті без світлофора діє правило пріоритету: як правило, поступаються дорогою тому, хто рухається по головній дорозі, або тому, хто наближається справа, якщо доріг рівнозначні. На кільцевій розв'язці пріоritet має транспорт, що вже рухається по колу або наближається з боку, визначеного знаками (в Ірландії — зазвичай той, хто вже на колі). Правильна відповідь у цій темі завжди відображає, хто саме має право проїхати першим згідно з цією ієрархією.", "explSpecific": "Правильна відповідь тут — «Водитель должен уступить дорогу транспорту, движущемуся справа или уже находящемуся на кольцевой развязке». Інші варіанти в цьому питанні («На кольцевой развязке водитель должен уступать дорогу только большегрузным транспортным средствам», «Водитель, приближающийся к кольцевой развязке, всегда имеет преимущественное право проезда» та «На кольцевой развязке водитель должен уступать дорогу только пешеходам и велосипедистам») не відповідають цій вимозі й тому неправильні."}, {"num": 441, "text": "В каком направлении должен поворачивать водитель при въезде на кольцевую развязку?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Направо.", "Налево и направо.", "Направо при движении, регулируемом светофором.", "Налево."], "correct": 3, "expl": "Форма і колір знаку самі по собі несуть значення, ще до того, як прочитано текст. Червоний восьмикутник — це завжди STOP: повна зупинка, незалежно від ситуації на дорозі. Червоне коло — заборона; трикутник із червоною облямівкою — попередження про небезпеку попереду; синє коло — обов'язкова вказівка (те, що треба зробити, а не те, чого не можна); синій або зелений прямокутник — інформаційний знак (напрямок, назва, відстань). Розмітка на дорозі працює за тією ж логікою: суцільна лінія забороняє перетин, переривчаста дозволяє за умови безпеки, подвійна суцільна діє найсуворіше в обох напрямках.", "explSpecific": "Правильна відповідь тут — «Налево». Інші варіанти в цьому питанні («Направо», «Налево и направо» та «Направо при движении, регулируемом светофором») не відповідають цій вимозі й тому неправильні."}]);
